// 6개월차 (Day 151~180) · ep 0,25,26,27,28,29,30
window.JJ_DAYS = Object.assign(window.JJ_DAYS || {}, {"151":{"day":151,"ep":"0","epTitle":"劇場版 呪術廻戦 0","epTitleKo":"극장판 주술회전 0","title":"〜ても構わない — 〜해도 상관없다","watch":"극장판 후반 · 게토의 백귀야행과 고전 습격 장면","scene":"12월 24일, 게토는 신주쿠와 교토에 저주를 풀어 백귀야행을 일으키고, 자신은 리카를 노리고 고전으로 쳐들어옵니다. 마키·판다·이누마키가 차례로 쓰러지자, 옷코츠는 친구들을 지키기 위해 모든 것을 걸 각오를 합니다.","lines":[{"who":"게토","ja":"邪魔をするなら、君たちが傷ついても構わないよ。","kana":"じゃまを するなら、きみたちが きずついても かまわないよ。","ko":"방해한다면 너희가 다쳐도 상관없어."},{"who":"옷코츠","ja":"僕はどうなっても構わない。みんなを守りたい。","kana":"ぼくは どう なっても かまわない。みんなを まもりたい。","ko":"난 어떻게 돼도 상관없어. 모두를 지키고 싶어."},{"who":"옷코츠","ja":"リカちゃん、お願いだ。力を全部貸してくれ。","kana":"リカちゃん、おねがいだ。ちからを ぜんぶ かして くれ。","ko":"리카, 부탁이야. 힘을 전부 빌려줘."}],"words":[{"w":"構う","r":"かまう","ko":"상관하다, 신경 쓰다"},{"w":"百鬼夜行","r":"ひゃっきやこう","ko":"백귀야행"},{"w":"襲う","r":"おそう","ko":"습격하다, 덮치다"},{"w":"誓い","r":"ちかい","ko":"맹세"},{"w":"覚悟","r":"かくご","ko":"각오"},{"w":"命","r":"いのち","ko":"목숨, 생명"},{"w":"恩","r":"おん","ko":"은혜"},{"w":"裏切る","r":"うらぎる","ko":"배신하다"}],"grammar":{"point":"〜ても構わない","desc":"〜ても構わない는 '〜해도 상관없다, 〜해도 괜찮다'라는 뜻입니다. 동사 て形+も構わない로 만들고, 정중하게는 〜ても構いません입니다. 명사·な형용사는 〜でも構わない(明日でも構いません)가 됩니다. 〜てもいい와 뜻은 비슷하지만 조금 더 격식 있고 '나는 괜찮다'는 양보의 느낌이 있습니다. 질문형 〜ても構いませんか는 '〜해도 괜찮을까요?'라는 공손한 허락 구하기입니다.","ex":[{"ja":"書類は来週提出しても構いません。","kana":"しょるいは らいしゅう ていしゅつ しても かまいません。","ko":"서류는 다음 주에 제출하셔도 괜찮습니다."},{"ja":"ここに座っても構いませんか。","kana":"ここに すわっても かまいませんか。","ko":"여기 앉아도 괜찮을까요?"}]},"convert":{"anime":"どうなっても構わねえ。","real":"どうなっても構いません。","note":"構わねえ는 構わない를 거칠게 발음한 남성 구어입니다. 업무에서는 構いません으로 말해야 합니다."},"mission":"고객이 상담 날짜를 바꾸고 싶어 합니다. '사정이 안 되시면 토요일이어도 괜찮다'고 말해 보세요.","missionEx":{"ja":"ご都合が悪ければ、土曜日でも構いません。","kana":"ごつごうが わるければ、どようびでも かまいません。","ko":"사정이 안 좋으시면 토요일이어도 괜찮습니다."},"quiz":[{"q":"「내일이어도 괜찮습니다」를 일본어로?","choices":["明日ても構いません","明日でも構いません","明日にも構いません"],"a":1,"why":"명사 뒤에는 でも構いません."},{"q":"「覚悟」의 읽기는?","choices":["かくご","かくごう","がくご"],"a":0,"why":"覚悟(かくご) = 각오. 覚悟を決める(각오를 다지다)."},{"q":"「여기서 전화해도 괜찮을까요?」를 일본어로?","choices":["ここで電話して構いますか","ここで電話するも構いませんか","ここで電話しても構いませんか"],"a":2,"why":"て形+も構いませんか로 공손하게 허락을 구합니다."}]},"152":{"day":152,"ep":"0","epTitle":"劇場版 呪術廻戦 0","epTitleKo":"극장판 주술회전 0","title":"응용 회화 — 극장판 총정리","watch":"극장판 클라이맥스 · 싸움이 끝난 뒤 리카와의 작별 장면","scene":"게토와의 싸움이 끝난 뒤, 리카의 저주가 풀리고 원래 모습의 리카가 옷코츠 앞에 나타납니다. 사실 리카를 이 세상에 붙잡아 둔 것은 옷코츠 쪽이었다는 것이 밝혀지고, 리카는 고마운 마음을 전하며 떠나갑니다.","lines":[{"who":"리카","ja":"憂太、ずっと一緒にいてくれて、ありがとう。","kana":"ゆうた、ずっと いっしょに いて くれて、ありがとう。","ko":"유타, 계속 함께 있어 줘서 고마워."},{"who":"옷코츠","ja":"もっと早く気づいてあげればよかった。ごめんね。","kana":"もっと はやく きづいて あげれば よかった。ごめんね。","ko":"더 빨리 알아챘으면 좋았을 텐데. 미안해."},{"who":"리카","ja":"泣かずに笑って。私はこのままで幸せだよ。","kana":"なかずに わらって。わたしは この ままで しあわせだよ。","ko":"울지 말고 웃어. 나는 이대로 행복해."}],"words":[{"w":"別れ","r":"わかれ","ko":"이별, 작별"},{"w":"愛","r":"あい","ko":"사랑"},{"w":"指輪","r":"ゆびわ","ko":"반지"},{"w":"幸せ","r":"しあわせ","ko":"행복, 행복하다"},{"w":"指切り","r":"ゆびきり","ko":"손가락 걸고 약속하기"},{"w":"結婚","r":"けっこん","ko":"결혼"},{"w":"恋しい","r":"こいしい","ko":"그립다"},{"w":"一生","r":"いっしょう","ko":"평생, 일생"}],"grammar":{"point":"응용 회화 — 극장판 총정리","desc":"① 〜ずに: 〜하지 않고 (確認せずに 확인하지 않고)\n② 〜まま: 〜한 채로 (座ったまま 앉은 채로 / そのまま 그대로)\n③ 〜ばよかった: 〜했으면 좋았을걸 (早く来ればよかった)\n④ 〜てくれてありがとう: 〜해 줘서 고마워 (정중: 〜てくださってありがとうございます)\n⑤ 〜ても構わない: 〜해도 상관없다 (明日でも構いません)","ex":[{"ja":"契約書は、そのままお持ち帰りいただいても構いません。","kana":"けいやくしょは、その まま おもちかえり いただいても かまいません。","ko":"계약서는 그대로 가져가셔도 괜찮습니다."},{"ja":"遠くから来てくださって、ありがとうございます。どうぞ座ったままで。","kana":"とおくから きて くださって、ありがとう ございます。どうぞ すわった ままで。","ko":"멀리서 와 주셔서 감사합니다. 앉으신 채로 계세요."}]},"convert":{"anime":"ずっと一緒にいてくれて、サンキューな。","real":"長い間一緒にいてくださって、ありがとうございました。","note":"サンキューな는 친한 사이의 가벼운 남성 말투입니다. 오랜 고객이나 은사께는 〜てくださって、ありがとうございました로 마무리합니다."},"mission":"롤플레이: 일본인 고객이 「もっと早く保険に入ればよかった」라고 말합니다. ① 공감하고 ② 상담에 와 줘서 고맙다고 하고 ③ 서류는 오늘 안 가져와도 괜찮다고 말해 보세요.","missionEx":{"ja":"今日は来てくださってありがとうございます。書類は今日じゃなくても構いません。","kana":"きょうは きて くださって ありがとう ございます。しょるいは きょう じゃなくても かまいません。","ko":"오늘 와 주셔서 감사합니다. 서류는 오늘이 아니어도 괜찮습니다."},"quiz":[{"q":"「울지 않고」를 일본어로?","choices":["泣かずに","泣きずに","泣くずに"],"a":0,"why":"泣かない에서 ない를 빼고 ずに → 泣かずに."},{"q":"「반지」는 일본어로?","choices":["愛","指輪","別れ"],"a":1,"why":"指輪(ゆびわ) = 반지. 愛는 사랑, 別れ는 이별."},{"q":"「더 일찍 연락할걸 그랬다」를 일본어로?","choices":["もっと早く連絡するばよかった","もっと早く連絡してよかった","もっと早く連絡すればよかった"],"a":2,"why":"する의 ば形은 すれば → 連絡すればよかった."}]},"153":{"day":153,"ep":"25","epTitle":"懐玉","epTitleKo":"회옥","title":"〜なさい — ~하거라, ~하렴 (윗사람의 지시)","watch":"25화 초반 · 야가 학장이 고죠·게토에게 호위 임무를 맡기는 장면","scene":"2006년, 고전 2학년인 고죠 사토루와 게토 스구루는 야가 학장에게서 특별한 임무를 받는다. 천원(텐겐)과 동화할 운명인 '성장체(星漿体)' 소녀 아마나이 리코를 지켜 무사히 데려가라는 것. 처음 만난 리코는 자기를 '妾(わらわ)'라고 부르며 두 사람에게 당당하게 명령한다.","lines":[{"who":"야가","ja":"二人で星漿体の少女を護衛し、安全に届けなさい。","kana":"ふたりで せいしょうたいの しょうじょを ごえいし、あんぜんに とどけなさい。","ko":"둘이서 성장체 소녀를 호위해 안전하게 데려다주도록."},{"who":"리코","ja":"お前たち、妾の言うことをちゃんと聞きなさい！","kana":"おまえたち、わらわの いう ことを ちゃんと ききなさい！","ko":"너희들, 내 말을 잘 듣거라!"},{"who":"게토","ja":"悟、相手は女の子だ。もう少し丁寧に話しなさい。","kana":"さとる、あいては おんなのこだ。もう すこし ていねいに はなしなさい。","ko":"사토루, 상대는 여자아이야. 좀 더 정중하게 말하렴."}],"words":[{"w":"生意気","r":"なまいき","ko":"건방짐"},{"w":"護衛","r":"ごえい","ko":"호위"},{"w":"荷造り","r":"にづくり","ko":"짐 꾸리기"},{"w":"真面目","r":"まじめ","ko":"성실함"},{"w":"出迎え","r":"でむかえ","ko":"마중"},{"w":"届ける","r":"とどける","ko":"전해 주다, 데려다주다"},{"w":"安全","r":"あんぜん","ko":"안전"},{"w":"年下","r":"としした","ko":"연하, 손아래"}],"grammar":{"point":"〜なさい","desc":"동사 ます형에서 ます를 떼고 なさい를 붙이면 '~하거라, ~하렴'이라는 지시가 됩니다(聞きます→聞きなさい, 急ぎます→急ぎなさい, します→しなさい). 부모가 자녀에게, 선생님이 학생에게처럼 윗사람이 아랫사람에게 쓰는 말이라, 명령형(聞け)보다는 부드럽지만 분명히 '위에서 내리는 지시'입니다. 그래서 고객이나 상사에게 쓰면 큰 실례이고, 그때는 〜てください나 お〜ください를 씁니다. 시험 문제 지시문(「正しいものを選びなさい」)에서도 자주 보입니다.","ex":[{"ja":"明日は学校でしょう。早く寝なさい。","kana":"あしたは がっこう でしょう。はやく ねなさい。","ko":"내일 학교잖아. 얼른 자렴."},{"ja":"書類は必ず二回確認しなさいと部長に言われました。","kana":"しょるいは かならず にかい かくにん しなさいと ぶちょうに いわれました。","ko":"서류는 반드시 두 번 확인하라고 부장님께 들었습니다."}]},"convert":{"anime":"早く準備しなさい！","real":"お早めにご準備をお願いいたします。","note":"なさい는 부모·선생님이 아이에게 하는 지시라 고객에게 쓰면 '가르치려 드는' 느낌이 납니다. 고객 응대에서는 お〜をお願いいたします나 〜てください로 바꿉니다."},"mission":"저녁에 딸에게 '밥 먹기 전에 손 씻어'라고 なさい로 말해 보세요. 그다음 같은 내용을 손님에게 하듯 정중하게 바꿔 보세요(お手をお洗いください).","missionEx":{"ja":"ご飯の前に手を洗いなさい。","kana":"ごはんの まえに てを あらいなさい。","ko":"밥 먹기 전에 손 씻으렴."},"quiz":[{"q":"「急ぐ(서두르다)」를 なさい형으로 바꾸면?","choices":["急ぎなさい","急ぐなさい","急いでなさい"],"a":0,"why":"ます형 急ぎます에서 ます를 떼고 なさい → 急ぎなさい."},{"q":"「護衛」의 읽기는?","choices":["しゅえい","ごえい","ごうえい"],"a":1,"why":"護衛는 ごえい(호위)라고 읽습니다."},{"q":"고객에게 '여기에 적어 주세요'라고 할 때 가장 알맞은 말은?","choices":["こちらに書きなさい。","ここに書け。","こちらにご記入ください。"],"a":2,"why":"なさい·명령형은 윗사람이 아랫사람에게 쓰는 말. 고객에게는 ご記入ください."}]},"155":{"day":155,"ep":"25","epTitle":"懐玉","epTitleKo":"회옥","title":"금지형 〜な — ~하지 마 (강한 금지)","watch":"25화 중반 · 리코를 노리는 자들이 학교까지 쫓아오는 장면","scene":"리코를 노리는 세력은 하나가 아니다. 주저사 집단 'Q'와 성장체를 숭배하는 종교 단체가 각각 리코를 노리고, 습격은 리코가 다니는 학교까지 이어진다. 고죠와 게토는 역할을 나눠 적을 상대하고 리코를 지키며, 고죠는 여유만만한 태도를 잃지 않는다.","lines":[{"who":"고죠","ja":"俺たち最強がいるんだから、そんなに慌てるな。","kana":"おれたち さいきょうが いるんだから、そんなに あわてるな。","ko":"최강인 우리가 있으니까 그렇게 허둥대지 마."},{"who":"게토","ja":"悟、敵を甘く見るな。こんな時こそ油断するなよ。","kana":"さとる、てきを あまく みるな。こんな ときこそ ゆだん するなよ。","ko":"사토루, 적을 얕보지 마. 이럴 때일수록 방심하지 말라고."},{"who":"리코","ja":"妾の学校で勝手に騒ぐな！みんなに迷惑じゃ！","kana":"わらわの がっこうで かってに さわぐな！みんなに めいわくじゃ！","ko":"내 학교에서 멋대로 소란 피우지 마라! 다들 곤란하지 않느냐!"}],"words":[{"w":"油断","r":"ゆだん","ko":"방심"},{"w":"意地悪","r":"いじわる","ko":"심술궂음, 심술쟁이"},{"w":"慌てる","r":"あわてる","ko":"허둥대다, 당황하다"},{"w":"内緒","r":"ないしょ","ko":"비밀"},{"w":"狙う","r":"ねらう","ko":"노리다"},{"w":"嘘つき","r":"うそつき","ko":"거짓말쟁이"},{"w":"おしゃべり","r":"おしゃべり","ko":"수다, 수다쟁이"},{"w":"いたずら","r":"いたずら","ko":"장난"}],"grammar":{"point":"금지형 〜な","desc":"동사 사전형(기본형)에 な를 붙이면 '~하지 마'라는 강한 금지가 됩니다(慌てる→慌てるな, 騒ぐ→騒ぐな, する→するな). 한국어 '~하지 마!'보다 더 거칠고 단호하며, 주로 남성이 친구·후배에게 쓰거나 표지판·경고문에 쓰입니다. 일상에서는 〜ないで(반말)나 〜ないでください(정중)가 기본이라는 것을 꼭 기억하세요. 주의: 앞에서 배운 なさい(ます형+なさい)와 헷갈리지 않도록, な는 '사전형+な'입니다.","ex":[{"ja":"危険！この線から先に入るな。","kana":"きけん！この せんから さきに はいるな。","ko":"위험! 이 선 너머로 들어가지 마시오."},{"ja":"「無理するな」と先輩が声をかけてくれました。","kana":"「むり するな」と せんぱいが こえを かけて くれました。","ko":"'무리하지 마'라고 선배가 말을 걸어 주었습니다."}]},"convert":{"anime":"慌てるな。","real":"どうぞ慌てないでください。ゆっくりで大丈夫です。","note":"〜な는 거칠고 위압적인 금지라 고객에게는 절대 쓰지 않습니다. 〜ないでください에 '천천히 하셔도 괜찮습니다' 같은 배려의 말을 붙이면 응대 말투가 됩니다."},"mission":"실수해서 풀이 죽은 친한 후배에게 '신경 쓰지 마, 다음에 잘하자'라고 〜な를 써서 격려해 보세요. 고객이었다면 어떻게 말할지도 함께 떠올려 보세요(お気になさらないでください).","missionEx":{"ja":"気にするな。次は頑張ろう。","kana":"きに するな。つぎは がんばろう。","ko":"신경 쓰지 마. 다음엔 힘내자."},"quiz":[{"q":"「騒ぐ(떠들다)」의 금지형은?","choices":["騒ぎな","騒がな","騒ぐな"],"a":2,"why":"금지형은 사전형+な → 騒ぐな. 騒ぎな는 なさい를 줄인 부드러운 지시라 뜻이 반대입니다."},{"q":"「油断するな」의 뜻은?","choices":["방심해라","방심하지 마","방심했니?"],"a":1,"why":"する의 사전형+な → するな(~하지 마)."},{"q":"불안해하는 고객에게 '걱정하지 마세요'라고 할 때 알맞은 말은?","choices":["ご心配なさらないでください。","心配するな。","心配しなさい。"],"a":0,"why":"〜な는 거친 금지. 고객에게는 ご心配なさらないでください."}]},"156":{"day":156,"ep":"25","epTitle":"懐玉","epTitleKo":"회옥","title":"〜って — ~래, ~란 (구어 인용·화제)","watch":"25화 전반부 · 고죠·게토가 임무 내용을 이야기하는 장면","scene":"임무를 받은 고죠와 게토는 '성장체'가 무엇인지, 왜 리코를 지켜야 하는지 이야기를 나눈다. 리코는 천원과 동화해 결계를 지탱하는 역할을 맡게 되고, 그 동화를 막으려는 조직들이 리코를 노린다. 리코 곁에는 늘 그녀를 돌보는 시녀 쿠로이 미사토가 있다.","lines":[{"who":"고죠","ja":"なあ傑、星漿体って、要するにどういう存在なの？","kana":"なあ すぐる、せいしょうたいって、ようするに どういう そんざい なの？","ko":"야 스구루, 성장체라는 게 결국 어떤 존재야?"},{"who":"게토","ja":"天元様と同化する子だって。夜蛾先生が言ってたよ。","kana":"てんげんさまと どうか する こ だって。やがせんせいが いってたよ。","ko":"텐겐 님과 동화하는 아이래. 야가 선생님이 그러던데."},{"who":"쿠로이","ja":"お嬢様を狙う組織があるって、本当ですか。","kana":"おじょうさまを ねらう そしきが あるって、ほんとう ですか。","ko":"아가씨를 노리는 조직이 있다는 게 정말인가요?"}],"words":[{"w":"縁","r":"えん","ko":"인연"},{"w":"付き合い","r":"つきあい","ko":"교제, 어울림"},{"w":"組織","r":"そしき","ko":"조직"},{"w":"恋人","r":"こいびと","ko":"연인"},{"w":"彼氏","r":"かれし","ko":"남자친구"},{"w":"関係","r":"かんけい","ko":"관계"},{"w":"告白","r":"こくはく","ko":"고백"},{"w":"同化","r":"どうか","ko":"동화(하나로 합쳐짐)"}],"grammar":{"point":"〜って (구어 인용·화제)","desc":"って는 회화에서 아주 많이 쓰이는 만능 조사입니다. ① 인용: 〜と言った의 と 대신 って(来るって言ってた = 온다고 했어). ② 전언: 문장 끝 〜って / 〜だって = '~래'(中止だって = 중지래). ③ 화제: 〜は·〜というのは 대신 '~란, ~라는 게'(星漿体って何？ = 성장체란 뭐야?). 편한 말투라서, 회사 보고나 고객 응대에서는 と / 〜そうです / 〜というのは로 바꿔 말합니다.","ex":[{"ja":"田中さんが今日は休むって言っていました。","kana":"たなかさんが きょうは やすむって いって いました。","ko":"다나카 씨가 오늘은 쉰다고 했어요."},{"ja":"「解約返戻金」って、どういう意味ですか。","kana":"「かいやく へんれいきん」って、どういう いみ ですか。","ko":"'해약환급금'이라는 게 무슨 뜻인가요?"}]},"convert":{"anime":"会議、中止だって。","real":"本日の会議は中止になったそうです。","note":"って는 친구·동료끼리의 구어입니다. 상사나 고객에게 전할 때는 〜そうです(~라고 합니다)나 〜とのことです로 바꾸면 깔끔합니다."},"mission":"동료에게 '고객님이 다음 주에 다시 온대'라고 って로 가볍게 전해 보세요. 그리고 같은 내용을 상사에게 〜そうです로 보고해 보세요.","missionEx":{"ja":"お客様、来週また来るって。","kana":"おきゃくさま、らいしゅう また くるって。","ko":"고객님, 다음 주에 또 오신대."},"quiz":[{"q":"「天元様って誰？」에서 って의 역할은?","choices":["이유(~때문에)","화제(~란, ~라는 사람은)","과거(~했다)"],"a":1,"why":"명사+って는 は·というのは처럼 화제를 꺼내는 역할입니다."},{"q":"'다나카 씨가 온대'를 구어로 바르게 말한 것은?","choices":["田中さん、来るって。","田中さん、来るて。","田中さん、来るっけ。"],"a":0,"why":"전언 '~래'는 보통형+って. っけ는 기억을 확인할 때 씁니다."},{"q":"「恋人」의 읽기는?","choices":["こいひと","れんじん","こいびと"],"a":2,"why":"恋人는 こいびと(연인). 人(ひと)가 뒤에 붙으며 びと로 탁음이 됩니다."}]},"157":{"day":157,"ep":"25","epTitle":"懐玉","epTitleKo":"회옥","title":"〜っけ — ~였더라?, ~였지? (기억 확인)","watch":"25화 후반부 · 리코가 학교 수업에 가겠다고 고집하는 장면","scene":"위험한 상황인데도 리코는 학교 수업만은 꼭 듣겠다고 고집한다. 친구들과 보내는 평범한 일상이 그녀에게는 무엇보다 소중하기 때문이다. 고죠와 게토는 투덜대면서도 일정과 장소를 확인하며 리코의 학교생활을 지켜 준다.","lines":[{"who":"리코","ja":"黒井、今日の午後の授業って何だったっけ？","kana":"くろい、きょうの ごごの じゅぎょうって なん だったっけ？","ko":"쿠로이, 오늘 오후 수업이 뭐였더라?"},{"who":"고죠","ja":"同化の日って、あと何日だったっけ？覚えてる？","kana":"どうかの ひって、あと なんにち だったっけ？おぼえてる？","ko":"동화하는 날이 앞으로 며칠 남았더라? 기억해?"},{"who":"게토","ja":"集合場所、どこだっけ？もう一度確認しよう。","kana":"しゅうごう ばしょ、どこ だっけ？もう いちど かくにん しよう。","ko":"집합 장소가 어디였지? 한 번 더 확인하자."}],"words":[{"w":"友人","r":"ゆうじん","ko":"친구(격식 있는 말)"},{"w":"記念写真","r":"きねんしゃしん","ko":"기념사진"},{"w":"親しい","r":"したしい","ko":"친하다"},{"w":"集合","r":"しゅうごう","ko":"집합"},{"w":"近所","r":"きんじょ","ko":"근처, 이웃"},{"w":"幼なじみ","r":"おさななじみ","ko":"소꿉친구"},{"w":"お祝い","r":"おいわい","ko":"축하"},{"w":"贈り物","r":"おくりもの","ko":"선물"}],"grammar":{"point":"〜っけ","desc":"っけ는 '분명 알았는데 기억이 가물가물할 때' 확인하는 말로, 한국어 '~였더라?', '~였지?'에 해당합니다. 명사·な형용사는 〜だっけ / 〜だったっけ, 동사는 과거형에 붙여 〜たっけ(言ったっけ = 말했던가?)가 기본입니다. 혼잣말로도 쓰고 상대에게 물을 때도 씁니다. 정중하게는 〜でしたっけ / 〜ましたっけ인데, 이것도 약간 편한 느낌이라 아주 격식 있는 자리에서는 '〜でしたでしょうか'를 씁니다.","ex":[{"ja":"打ち合わせは何時からでしたっけ。","kana":"うちあわせは なんじ から でしたっけ。","ko":"미팅이 몇 시부터였죠?"},{"ja":"この書類、もう提出しましたっけ。","kana":"この しょるい、もう ていしゅつ しましたっけ。","ko":"이 서류, 벌써 제출했던가요?"}]},"convert":{"anime":"名前、何だっけ？","real":"恐れ入りますが、お名前をもう一度伺ってもよろしいですか。","note":"〜だっけ는 친구끼리의 반말입니다. 고객의 이름을 잊었을 때 っけ로 물으면 실례가 되니, 恐れ入りますが로 시작해 다시 여쭤보는 표현을 씁니다."},"mission":"동료에게 다음 고객 상담이 무슨 요일이었는지 〜でしたっけ로 물어보세요. 장소나 시간도 바꿔서 한 번 더 물어보세요.","missionEx":{"ja":"次の面談は何曜日でしたっけ。","kana":"つぎの めんだんは なんようび でしたっけ。","ko":"다음 상담이 무슨 요일이었죠?"},"quiz":[{"q":"'회의 몇 시였더라?'를 일본어로?","choices":["会議は何時だな？","会議は何時って？","会議は何時だっけ？"],"a":2,"why":"기억을 확인할 때는 〜だっけ. って는 인용·전언입니다."},{"q":"「贈り物」의 뜻은?","choices":["선물","축하","소꿉친구"],"a":0,"why":"贈り物(おくりもの)는 '선물'. 축하는 お祝い, 소꿉친구는 幼なじみ입니다."},{"q":"「記念写真」의 읽기는?","choices":["きねんじゃしん","きねんしゃしん","きえんしゃしん"],"a":1,"why":"記念写真은 きねんしゃしん(기념사진)입니다."}]},"158":{"day":158,"ep":"26","epTitle":"懐玉-弐-","epTitleKo":"회옥 2","title":"축약 〜ちゃう / 〜じゃう — ~해 버리다","watch":"26화 전반부 · 쿠로이가 사라지고 일행이 오키나와로 향하는 장면","scene":"리코를 노리는 습격이 이어지는 가운데, 리코를 곁에서 돌봐 온 쿠로이가 적에게 붙잡혀 사라집니다. 적은 오키나와를 거래 장소로 정하고, 고죠와 게토는 리코와 함께 비행기를 타고 오키나와로 향합니다.","lines":[{"who":"리코","ja":"黒井さんが連れて行かれちゃった…どうしよう。","kana":"くろいさんが つれて いかれちゃった… どうしよう。","ko":"쿠로이 씨가 끌려가 버렸어… 어떡해."},{"who":"게토","ja":"落ち着いて。全部、私たちが片づけちゃうから。","kana":"おちついて。ぜんぶ、わたしたちが かたづけちゃう から。","ko":"진정해. 전부 우리가 해치워 버릴 테니까."},{"who":"고죠","ja":"じゃ、さっさと飛行機で沖縄まで飛んじゃおうぜ。","kana":"じゃ、さっさと ひこうきで おきなわまで とんじゃおうぜ。","ko":"그럼 얼른 비행기로 오키나와까지 날아가 버리자고."}],"words":[{"w":"沖縄","r":"おきなわ","ko":"오키나와"},{"w":"飛行機","r":"ひこうき","ko":"비행기"},{"w":"連れて行く","r":"つれていく","ko":"데려가다"},{"w":"乗り物","r":"のりもの","ko":"탈것"},{"w":"落とす","r":"おとす","ko":"떨어뜨리다, 잃어버리다"},{"w":"無くす","r":"なくす","ko":"잃어버리다"},{"w":"座席","r":"ざせき","ko":"좌석"},{"w":"窓側","r":"まどがわ","ko":"창가 쪽"}],"grammar":{"point":"〜ちゃう / 〜じゃう (축약)","desc":"〜てしまう(~해 버리다)를 회화에서 줄인 말이 〜ちゃう입니다. て가 で로 끝나는 동사는 〜でしまう → 〜じゃう가 됩니다(飲んでしまう → 飲んじゃう). 과거형은 〜ちゃった / 〜じゃった입니다. '다 끝내 버렸다'는 완료, 또는 '실수로 ~해 버렸다'는 아쉬움을 나타내며, 한국어 '~해 버렸어'와 거의 같습니다. 친한 사이의 말투이므로 업무 자리에서는 〜てしまいました로 바꿉니다.","ex":[{"ja":"大事な書類を家に忘れちゃいました。","kana":"だいじな しょるいを いえに わすれちゃいました。","ko":"중요한 서류를 집에 두고 와 버렸어요."},{"ja":"昨日は会食で少し飲んじゃいました。","kana":"きのうは かいしょくで すこし のんじゃいました。","ko":"어제는 회식에서 조금 마셔 버렸어요."}]},"convert":{"anime":"書類、無くしちゃった。","real":"書類を無くしてしまいました。申し訳ありません。","note":"〜ちゃった는 친구나 가족에게 쓰는 축약형입니다. 고객이나 상사에게 실수를 알릴 때는 〜てしまいました로 풀어 말하고 사과 표현을 붙입니다."},"mission":"최근에 실수로 '~해 버린' 일을 〜ちゃった로 말해 보세요. 예: 고객 미팅 자료를 차에 두고 와 버렸다.","missionEx":{"ja":"お客様の資料を車に置いてきちゃった。","kana":"おきゃくさまの しりょうを くるまに おいて きちゃった。","ko":"고객 자료를 차에 두고 와 버렸어."},"quiz":[{"q":"「飲んでしまう」의 축약형은?","choices":["飲んちゃう","飲んじゃう","飲みちゃう"],"a":1,"why":"て형이 〜んで로 끝나면 〜でしまう → 〜じゃう가 됩니다."},{"q":"「서류를 잃어버렸습니다」(정중)를 일본어로?","choices":["書類を無くしてしまいました。","書類を無くしちゃった。","書類を無くしちゃうです。"],"a":0,"why":"업무에서는 축약하지 않은 〜てしまいました가 알맞습니다."},{"q":"「窓側」의 뜻은?","choices":["통로 쪽","좌석","창가 쪽"],"a":2,"why":"窓側(まどがわ)는 '창가 쪽'. 통로 쪽은 通路側, 좌석은 座席입니다."}]},"159":{"day":159,"ep":"26","epTitle":"懐玉-弐-","epTitleKo":"회옥 2","title":"축약 〜てる / 〜とく — ~하고 있어 / ~해 둘게","watch":"26화 중반 · 오키나와 바다와 수족관에서 리코가 즐거워하는 장면","scene":"일이 일단락된 뒤, 일행은 오키나와에 조금 더 머물며 리코에게 바다와 수족관을 즐기게 해 줍니다. 그사이 고죠는 리코를 지키기 위해 술식을 계속 켜 둔 채 거의 잠을 자지 않고 버팁니다.","lines":[{"who":"리코","ja":"見て見て！きれいな魚がいっぱい泳いでるよ！","kana":"みて みて！ きれいな さかなが いっぱい およいでるよ！","ko":"봐 봐! 예쁜 물고기가 잔뜩 헤엄치고 있어!"},{"who":"게토","ja":"帰りの飛行機の時間は、私がちゃんと調べとくよ。","kana":"かえりの ひこうきの じかんは、わたしが ちゃんと しらべとくよ。","ko":"돌아갈 비행기 시간은 내가 잘 알아봐 둘게."},{"who":"고죠","ja":"眠くないって。俺はずっと起きてるから平気だよ。","kana":"ねむくないって。おれは ずっと おきてる から へいき だよ。","ko":"안 졸리다니까. 난 계속 깨어 있으니까 괜찮아."}],"words":[{"w":"海","r":"うみ","ko":"바다"},{"w":"島","r":"しま","ko":"섬"},{"w":"水族館","r":"すいぞくかん","ko":"수족관"},{"w":"魚","r":"さかな","ko":"물고기, 생선"},{"w":"日焼け","r":"ひやけ","ko":"햇볕에 탐"},{"w":"浴衣","r":"ゆかた","ko":"유카타(여름 기모노)"},{"w":"旅館","r":"りょかん","ko":"료칸, 일본식 여관"},{"w":"空港","r":"くうこう","ko":"공항"}],"grammar":{"point":"〜てる / 〜とく (축약)","desc":"〜ている(~하고 있다)에서 い가 빠지면 〜てる가 됩니다(待っている → 待ってる). 〜ておく(~해 두다, 미리 해 놓다)는 〜とく로 줄어듭니다(調べておく → 調べとく). で로 끝나는 동사는 〜でる, 〜どく가 됩니다(読んでる, 読んどく). 일본인의 일상 회화에서 아주 자주 들리는 형태이며, 정중하게는 〜てます, 〜ときます처럼 ます를 붙여 쓰기도 합니다.","ex":[{"ja":"会議の資料、コピーしときますね。","kana":"かいぎの しりょう、こぴー しときますね。","ko":"회의 자료, 복사해 둘게요."},{"ja":"部長は今、お客様と話してます。","kana":"ぶちょうは いま、おきゃくさまと はなしてます。","ko":"부장님은 지금 고객님과 이야기하고 계세요."}]},"convert":{"anime":"ホテル、予約しとくよ。","real":"ホテルはこちらで予約しておきます。","note":"〜とく는 편한 사이의 축약형입니다. 고객 응대에서는 축약하지 않은 〜ておきます를 쓰고, 'こちらで(저희 쪽에서)'를 붙이면 더 정중하게 들립니다."},"mission":"내일 고객 상담을 위해 미리 해 둘 일을 〜とく 또는 〜ておきます로 말해 보세요. 예: 상담 전에 보험 증권을 확인해 두겠다.","missionEx":{"ja":"相談の前に、保険証券を確認しておきます。","kana":"そうだんの まえに、ほけん しょうけんを かくにん して おきます。","ko":"상담 전에 보험 증권을 확인해 두겠습니다."},"quiz":[{"q":"「調べておく」의 축약형은?","choices":["調べてく","調べとく","調べちゃう"],"a":1,"why":"〜ておく는 〜とく로 줄어듭니다."},{"q":"「泳いでいる」의 축약형은?","choices":["泳いでる","泳いどく","泳いじゃう"],"a":0,"why":"〜でいる에서 い가 빠져 〜でる가 됩니다."},{"q":"「水族館」의 읽는 법은?","choices":["すいえいかん","すいどうかん","すいぞくかん"],"a":2,"why":"水族館은 すいぞくかん(수족관)입니다."}]},"160":{"day":160,"ep":"26","epTitle":"懐玉-弐-","epTitleKo":"회옥 2","title":"〜なきゃ / 〜なくちゃ — ~해야 해","watch":"26화 후반부 · 오키나와를 떠나 도쿄로 돌아갈 준비를 하는 장면","scene":"즐거운 시간도 잠시, 리코를 정해진 날까지 고전으로 데려가야 하는 기한이 다가옵니다. 일행은 아쉬운 마음을 안고 오키나와를 떠나 도쿄로 돌아갈 준비를 합니다.","lines":[{"who":"게토","ja":"そろそろ出発しなきゃ。期限は明日だからね。","kana":"そろそろ しゅっぱつ しなきゃ。きげんは あした だからね。","ko":"슬슬 출발해야 해. 기한이 내일이니까."},{"who":"리코","ja":"えー、もう東京に帰らなくちゃいけないの？残念…。","kana":"えー、もう とうきょうに かえらなくちゃ いけないの？ ざんねん…。","ko":"에이, 벌써 도쿄로 돌아가야 하는 거야? 아쉽다…."},{"who":"고죠","ja":"荷物、早く片付けなきゃ置いてっちゃうぞ。","kana":"にもつ、はやく かたづけなきゃ おいてっちゃうぞ。","ko":"짐 빨리 안 챙기면 두고 가 버린다."}],"words":[{"w":"片道","r":"かたみち","ko":"편도"},{"w":"期限","r":"きげん","ko":"기한"},{"w":"残念","r":"ざんねん","ko":"유감, 아쉬움"},{"w":"往復","r":"おうふく","ko":"왕복"},{"w":"土産話","r":"みやげばなし","ko":"여행 다녀온 이야기"},{"w":"時刻表","r":"じこくひょう","ko":"(열차·비행기) 시간표"},{"w":"提出","r":"ていしゅつ","ko":"제출"},{"w":"夕方","r":"ゆうがた","ko":"저녁 무렵"}],"grammar":{"point":"〜なきゃ / 〜なくちゃ","desc":"〜なければならない(~해야 한다)를 회화에서 줄인 말이 〜なきゃ입니다. 〜なくてはいけない는 〜なくちゃ로 줄어듭니다. 만드는 법은 ない형에서 い를 빼고 きゃ/くちゃ를 붙입니다(行かない → 行かなきゃ, 食べない → 食べなくちゃ). 뒤의 いけない가 생략된 형태라서 혼잣말처럼 '~해야지'라는 느낌도 납니다. 정중하게 말할 때는 〜なければなりません, 〜ないといけません을 씁니다.","ex":[{"ja":"今日中に書類を提出しなきゃ。","kana":"きょうじゅうに しょるいを ていしゅつ しなきゃ。","ko":"오늘 안에 서류를 제출해야 해."},{"ja":"夕方までに見積もりを送らなくちゃいけないんです。","kana":"ゆうがたまでに みつもりを おくらなくちゃ いけないんです。","ko":"저녁까지 견적을 보내야 하거든요."}]},"convert":{"anime":"締め切り、明日までに出さなきゃ。","real":"締め切りが明日なので、それまでに提出しなければなりません。","note":"〜なきゃ는 혼잣말이나 친구 사이에서 쓰는 축약입니다. 고객이나 상사에게 기한을 안내할 때는 〜なければなりません처럼 끝까지 말해야 정확하고 정중합니다."},"mission":"이번 주에 꼭 해야 하는 업무를 〜なきゃ로 혼잣말하듯 말해 보세요. 예: 금요일까지 고객 청구 서류를 보내야 한다.","missionEx":{"ja":"金曜日までにお客様の請求書類を送らなきゃ。","kana":"きんようびまでに おきゃくさまの せいきゅう しょるいを おくらなきゃ。","ko":"금요일까지 고객 청구 서류를 보내야 해."},"quiz":[{"q":"「가야 해」(축약 반말)를 일본어로?","choices":["行かなくて。","行かないで。","行かなきゃ。"],"a":2,"why":"行かない의 い를 빼고 きゃ를 붙여 行かなきゃ가 됩니다."},{"q":"「食べなくちゃ」를 정중하게 바꾸면?","choices":["食べなければなりません。","食べないでください。","食べてもいいです。"],"a":0,"why":"〜なくちゃ의 정중형은 〜なければなりません입니다."},{"q":"「時刻表」의 뜻은?","choices":["출발","(열차·비행기) 시간표","예약"],"a":1,"why":"時刻表(じこくひょう)는 열차·버스 등의 운행 시간표입니다."}]},"162":{"day":162,"ep":"26","epTitle":"懐玉-弐-","epTitleKo":"회옥 2","title":"〜じゃん / 〜よね — ~잖아 / ~지?","watch":"26화 마지막 · 일행이 고전 결계 안으로 돌아와 한숨 돌리는 장면","scene":"일행은 무사히 도쿄로 돌아와 고전 결계 안에 들어서고, 이제 안심이라며 긴장을 풉니다. 하지만 이 화의 마지막에는 그 방심을 노린 예상치 못한 위기가 고죠에게 닥칩니다.","lines":[{"who":"고죠","ja":"ほら、無事に着いたじゃん。もう安心だろ。","kana":"ほら、ぶじに ついたじゃん。もう あんしん だろ。","ko":"봐, 무사히 도착했잖아. 이제 안심이지."},{"who":"리코","ja":"沖縄の海、すごくきれいで楽しかったよね。","kana":"おきなわの うみ、すごく きれいで たのしかったよね。","ko":"오키나와 바다, 엄청 예쁘고 즐거웠지?"},{"who":"게토","ja":"いい思い出になったよね。でも、気は抜くなよ。","kana":"いい おもいでに なったよね。でも、きは ぬくなよ。","ko":"좋은 추억이 됐지. 그래도 긴장은 풀지 마."}],"words":[{"w":"旅先","r":"たびさき","ko":"여행지"},{"w":"港","r":"みなと","ko":"항구"},{"w":"旅","r":"たび","ko":"여행"},{"w":"素敵","r":"すてき","ko":"멋짐"},{"w":"景色","r":"けしき","ko":"경치"},{"w":"地元","r":"じもと","ko":"고향 동네, 지역"},{"w":"緊張","r":"きんちょう","ko":"긴장"},{"w":"懐かしい","r":"なつかしい","ko":"그립다"}],"grammar":{"point":"〜じゃん / 〜よね","desc":"〜じゃん은 〜じゃないか를 줄인 말로, '~잖아'처럼 상대도 알 만한 사실을 들이밀 때 씁니다(できたじゃん = 했잖아). 〜よね는 '~지?, ~죠?'처럼 상대에게 동의나 확인을 구할 때 씁니다. よね는 です·ます 뒤에도 붙일 수 있어서(〜ですよね) 업무에서도 자주 쓰지만, じゃん은 친한 사이의 반말입니다. 정중하게 '~잖아요'를 말하려면 〜じゃないですか를 씁니다.","ex":[{"ja":"来週の打ち合わせは月曜日ですよね。","kana":"らいしゅうの うちあわせは げつようび ですよね。","ko":"다음 주 미팅은 월요일이죠?"},{"ja":"この資料、分かりやすいじゃん。","kana":"この しりょう、わかりやすいじゃん。","ko":"이 자료, 알기 쉽잖아."}]},"convert":{"anime":"契約、うまくいったじゃん。","real":"ご契約、無事に進んでよかったですね。","note":"〜じゃん은 친구끼리의 말투라 고객에게 쓰면 가볍게 들립니다. 고객과 결과를 함께 기뻐할 때는 〜てよかったですね로 바꾸면 자연스럽습니다."},"mission":"일본인 고객에게 다음 상담 일정이나 내용을 〜ですよね로 확인해 보세요. 예: 다음 상담은 목요일 오후 3시죠?","missionEx":{"ja":"次のご相談は木曜日の三時ですよね。","kana":"つぎの ごそうだんは もくようびの さんじ ですよね。","ko":"다음 상담은 목요일 3시죠?"},"quiz":[{"q":"「무사히 도착했잖아」(반말)를 일본어로?","choices":["無事に着いたよね。","無事に着いたじゃん。","無事に着くじゃない。"],"a":1,"why":"'~잖아'처럼 사실을 들이밀 때는 〜じゃん을 씁니다."},{"q":"고객에게 '월요일이죠?'라고 확인할 때 알맞은 것은?","choices":["月曜日じゃん。","月曜日だよ。","月曜日ですよね。"],"a":2,"why":"〜ですよね는 정중하게 확인할 때 쓸 수 있습니다."},{"q":"「旅先」의 뜻은?","choices":["여행지","경치","긴장"],"a":0,"why":"旅先(たびさき)는 '여행지, 여행 간 곳'입니다."}]},"163":{"day":163,"ep":"27","epTitle":"懐玉-参-","epTitleKo":"회옥 3","title":"〜ば〜ほど — ~하면 ~할수록","watch":"27화 초반 · 현상금 기한이 지나고 고전으로 돌아온 장면","scene":"오키나와에서 돌아온 고죠와 게토는 리코를 데리고 고전 결계 안으로 들어온다. 현상금 기한이 지나 모두 한숨 돌리지만, 고죠는 며칠 동안 술식을 계속 켜 두어 지쳐 있다. 그 틈을 노리고 후시구로 토우지가 조용히 기다리고 있었다.","lines":[{"who":"토우지","ja":"待てば待つほど、相手は油断するもんだ。","kana":"まてば まつほど、あいては ゆだん する もんだ。","ko":"기다리면 기다릴수록 상대는 방심하는 법이지."},{"who":"고죠","ja":"術式は使えば使うほど、頭が疲れるんだよね。","kana":"じゅつしきは つかえば つかうほど、あたまが つかれるんだよね。","ko":"술식은 쓰면 쓸수록 머리가 피곤해진단 말이지."},{"who":"게토","ja":"考えれば考えるほど、この任務は妙だな。","kana":"かんがえれば かんがえるほど、この にんむは みょうだな。","ko":"생각하면 생각할수록 이 임무는 이상해."}],"words":[{"w":"頼み","r":"たのみ","ko":"부탁"},{"w":"仲","r":"なか","ko":"사이"},{"w":"付き合う","r":"つきあう","ko":"사귀다, 어울리다"},{"w":"年上","r":"としうえ","ko":"연상, 손위"},{"w":"気楽","r":"きらく","ko":"마음 편함"},{"w":"気が合う","r":"きがあう","ko":"마음이 맞다"},{"w":"親孝行","r":"おやこうこう","ko":"효도"},{"w":"気軽","r":"きがる","ko":"부담 없음"}],"grammar":{"point":"〜ば〜ほど","desc":"〜ば〜ほど는 '~하면 ~할수록'이라는 뜻으로, 앞의 정도가 커질수록 뒤의 결과도 함께 변한다는 비례 관계를 나타냅니다. 같은 말을 두 번 써서 '가정형(ば) + 사전형(ほど)'으로 만듭니다: 待つ→待てば待つほど, 考える→考えれば考えるほど. い형용사는 安い→安ければ安いほど, な형용사는 簡単なら簡単なほど(簡単であればあるほど)가 됩니다. 한국어 '~할수록'과 거의 같아서 금방 익숙해질 수 있습니다.","ex":[{"ja":"準備すればするほど、お客様との相談はうまくいきます。","kana":"じゅんび すれば するほど、おきゃくさまとの そうだんは うまく いきます。","ko":"준비하면 할수록 고객과의 상담은 잘 풀립니다."},{"ja":"保険は若ければ若いほど、保険料が安くなります。","kana":"ほけんは わかければ わかいほど、ほけんりょうが やすく なります。","ko":"보험은 젊으면 젊을수록 보험료가 싸집니다."}]},"convert":{"anime":"考えりゃ考えるほど、わけわかんねえ。","real":"考えれば考えるほど、よく分からなくなります。","note":"考えりゃ는 考えれば의 거친 구어 축약이고 わかんねえ는 남성 반말입니다. 회사나 고객 앞에서는 축약 없이 考えれば와 分からなくなります로 말합니다."},"mission":"고객에게 '빨리 시작할수록 유리하다'는 점을 〜ば〜ほど로 설명해 보세요. (예: 저축, 연금, 보험 가입)","missionEx":{"ja":"貯金は早く始めれば始めるほど、有利です。","kana":"ちょきんは はやく はじめれば はじめるほど、ゆうりです。","ko":"저축은 일찍 시작하면 할수록 유리합니다."},"quiz":[{"q":"「먹으면 먹을수록 살찐다」를 일본어로?","choices":["食べると食べたほど太る。","食べたら食べるほど太る。","食べれば食べるほど太る。"],"a":2,"why":"가정형 食べれば + 사전형 食べるほど 형태가 맞습니다."},{"q":"安い를 〜ば〜ほど로 바르게 바꾼 것은?","choices":["安ければ安いほど","安いれば安いほど","安くば安くほど"],"a":0,"why":"い형용사는 い를 ければ로 바꾸고 뒤는 安いほど로 씁니다."},{"q":"「気楽」의 뜻은?","choices":["사이","마음 편함","연상"],"a":1,"why":"気楽(きらく)는 '마음 편함'. 사이는 仲, 연상은 年上입니다."}]},"164":{"day":164,"ep":"27","epTitle":"懐玉-参-","epTitleKo":"회옥 3","title":"〜たびに — ~할 때마다","watch":"27화 전반부 · 고죠와 토우지의 첫 대결","scene":"결계 입구에서 토우지가 기척 없이 나타나 고죠를 뒤에서 기습한다. 주력이 전혀 없는 토우지는 움직일 때마다 존재감이 사라져 고죠조차 알아채기 어렵다. 고죠는 큰 부상을 입고도 게토에게 리코를 맡기며 먼저 가라고 한다.","lines":[{"who":"고죠","ja":"あいつ、攻撃のたびに気配が消えるんだよな。","kana":"あいつ、こうげきの たびに けはいが きえるんだよな。","ko":"저 녀석, 공격할 때마다 기척이 사라진단 말이야."},{"who":"토우지","ja":"術師の顔を見るたびに、昔の家を思い出すぜ。","kana":"じゅつしの かおを みる たびに、むかしの いえを おもいだすぜ。","ko":"술사 얼굴을 볼 때마다 옛날 집이 생각나."},{"who":"게토","ja":"悟は戦うたびに、余裕の顔をするんだから。","kana":"さとるは たたかう たびに、よゆうの かおを するんだから。","ko":"사토루는 싸울 때마다 여유로운 표정을 짓는다니까."}],"words":[{"w":"出会う","r":"であう","ko":"(우연히) 만나다"},{"w":"気配","r":"けはい","ko":"기척, 낌새"},{"w":"思い出す","r":"おもいだす","ko":"떠올리다, 생각나다"},{"w":"家出","r":"いえで","ko":"가출"},{"w":"背中","r":"せなか","ko":"등"},{"w":"親父","r":"おやじ","ko":"아버지(허물없는 말)"},{"w":"余裕","r":"よゆう","ko":"여유"},{"w":"訪ねる","r":"たずねる","ko":"찾아가다, 방문하다"}],"grammar":{"point":"〜たびに","desc":"〜たびに는 '~할 때마다'라는 뜻으로, 어떤 일이 일어날 때마다 항상 같은 결과가 따라온다는 것을 나타냅니다. 동사는 사전형에 붙이고(見るたびに・会うたびに), 명사는 の를 넣어 攻撃のたびに・出張のたびに처럼 씁니다. 〜時はいつも와 비슷하지만 '반복될 때마다 매번'이라는 느낌이 더 강합니다. 과거형(見たたびに)에는 붙이지 않는다는 점에 주의하세요.","ex":[{"ja":"この写真を見るたびに、家族旅行を思い出します。","kana":"この しゃしんを みる たびに、かぞく りょこうを おもいだします。","ko":"이 사진을 볼 때마다 가족 여행이 떠오릅니다."},{"ja":"お客様に会うたびに、新しいことを学びます。","kana":"おきゃくさまに あう たびに、あたらしい ことを まなびます。","ko":"고객을 만날 때마다 새로운 것을 배웁니다."}]},"convert":{"anime":"会うたびに文句ばっか言いやがって。","real":"お会いするたびに、貴重なご意見をいただき、ありがとうございます。","note":"ばっか는 ばかり의 축약, 〜やがって는 상대를 깔보는 거친 말입니다. 고객의 불만도 업무에서는 '귀중한 의견'으로 받아 お会いするたびに로 정중하게 감사를 전합니다."},"mission":"어떤 일을 할 때마다 늘 생기는 습관이나 느낌을 〜たびに로 말해 보세요. (예: 일본 여행, 고객 상담, 딸과의 외출)","missionEx":{"ja":"日本に行くたびに、ラーメンを食べます。","kana":"にほんに いく たびに、らーめんを たべます。","ko":"일본에 갈 때마다 라멘을 먹습니다."},"quiz":[{"q":"「갈 때마다」를 일본어로?","choices":["行ったたびに","行くたびに","行きたびに"],"a":1,"why":"たびに 앞의 동사는 사전형(行く)을 씁니다."},{"q":"명사 出張에 たびに를 붙인 올바른 형태는?","choices":["出張たびに","出張なたびに","出張のたびに"],"a":2,"why":"명사는 の를 넣어 〜のたびに가 됩니다."},{"q":"「気配」의 뜻은?","choices":["기척, 낌새","공격","여유"],"a":0,"why":"気配(けはい)는 '기척, 낌새'입니다."}]},"165":{"day":165,"ep":"27","epTitle":"懐玉-参-","epTitleKo":"회옥 3","title":"〜うちに — ~하는 동안에 / ~하기 전에","watch":"27화 중반 · 지하 깊은 곳, 리코의 선택 장면","scene":"게토는 리코를 데리고 덴겐이 있는 지하 깊은 곳까지 내려간다. 게토는 동화를 원하지 않는다면 함께 돌아가도 된다고 말하고, 리코는 며칠 동안 친구들과 지내며 더 살고 싶어졌다고 솔직하게 털어놓는다. 게토는 그 선택을 받아들이고 손을 내민다.","lines":[{"who":"게토","ja":"迷っているなら、今のうちに言ってほしい。","kana":"まよって いるなら、いまの うちに いって ほしい。","ko":"망설이고 있다면 지금 말해 줬으면 해."},{"who":"리코","ja":"みんなといるうちに、もっと生きたくなったの。","kana":"みんなと いる うちに、もっと いきたく なったの。","ko":"다들이랑 함께 있는 동안 더 살고 싶어졌어."},{"who":"게토","ja":"じゃあ、誰にも見つからないうちに戻ろう。","kana":"じゃあ、だれにも みつからない うちに もどろう。","ko":"그럼 누구한테도 들키기 전에 돌아가자."}],"words":[{"w":"恩返し","r":"おんがえし","ko":"은혜 갚기"},{"w":"打ち解ける","r":"うちとける","ko":"마음을 터놓다"},{"w":"外国","r":"がいこく","ko":"외국"},{"w":"抱きしめる","r":"だきしめる","ko":"꼭 껴안다"},{"w":"見学","r":"けんがく","ko":"견학"},{"w":"結婚式","r":"けっこんしき","ko":"결혼식"},{"w":"名残惜しい","r":"なごりおしい","ko":"(헤어지기) 아쉽다"},{"w":"見つかる","r":"みつかる","ko":"발견되다, 들키다"}],"grammar":{"point":"〜うちに","desc":"〜うちに는 두 가지로 씁니다. ① '~하는 동안에(어느새)': みんなといるうちに好きになった처럼 어떤 상태가 계속되는 사이에 변화가 생길 때. ② '~할 때(상태가 바뀌기 전에)': 若いうちに・今のうちに처럼 그 상태가 끝나기 전에 해 두자는 뜻입니다. ②는 부정형과 자주 어울려 忘れないうちに(잊기 전에)·暗くならないうちに(어두워지기 전에)처럼 씁니다. 동사는 보통형, い형용사는 그대로, な형용사는 な, 명사는 の를 붙입니다.","ex":[{"ja":"若いうちに、老後の準備を始めましょう。","kana":"わかい うちに、ろうごの じゅんびを はじめましょう。","ko":"젊을 때 노후 준비를 시작합시다."},{"ja":"忘れないうちに、メモしておきます。","kana":"わすれない うちに、めも して おきます。","ko":"잊어버리기 전에 메모해 두겠습니다."}]},"convert":{"anime":"今のうちに決めちゃえよ。","real":"今のうちにお決めになったほうがよろしいかと思います。","note":"決めちゃえ는 決めてしまえ의 축약 명령형이라 고객에게 쓰면 강요처럼 들립니다. お決めになる(존경어)와 〜ほうがよろしいかと思います로 부드럽게 권합니다."},"mission":"고객에게 '건강할 때(젊을 때) 미리 준비하자'는 내용을 〜うちに로 권해 보세요.","missionEx":{"ja":"健康なうちに、保険に入っておきましょう。","kana":"けんこうな うちに、ほけんに はいって おきましょう。","ko":"건강할 때 보험에 들어 둡시다."},"quiz":[{"q":"「젊을 때 여행하고 싶다」를 일본어로?","choices":["若いうちに旅行したい。","若くうちに旅行したい。","若いのうちに旅行したい。"],"a":0,"why":"い형용사는 그대로 うちに를 붙입니다."},{"q":"「잊어버리기 전에」에 가장 알맞은 표현은?","choices":["忘れたうちに","忘れるうちに","忘れないうちに"],"a":2,"why":"'~하기 전에'는 부정형 + うちに(忘れないうちに)로 자주 씁니다."},{"q":"「外国」의 뜻은?","choices":["마음을 터놓다","외국","견학"],"a":1,"why":"外国(がいこく)는 '외국'. 마음을 터놓다는 打ち解ける, 견학은 見学입니다."}]},"166":{"day":166,"ep":"27","epTitle":"懐玉-参-","epTitleKo":"회옥 3","title":"〜間 / 〜間に — ~동안 (내내) / ~동안에","watch":"27화 후반부 · 게토와 토우지의 대결","scene":"고죠를 쓰러뜨린 토우지가 지하까지 뒤쫓아와 리코를 공격하고, 리코는 그대로 쓰러진다. 분노한 게토는 거느린 주령들을 불러내 맞서지만, 토우지는 무기를 바꿔 가며 게토를 압도한다. 결국 게토도 쓰러지고 만다.","lines":[{"who":"토우지","ja":"お前らが話している間に、ここまで来たぜ。","kana":"おまえらが はなして いる あいだに、ここまで きたぜ。","ko":"너희가 얘기하는 사이에 여기까지 왔지."},{"who":"게토","ja":"私が戦っている間、この子には近づかせない。","kana":"わたしが たたかって いる あいだ、この こには ちかづかせない。","ko":"내가 싸우는 동안은 이 아이에게 다가가게 두지 않겠어."},{"who":"토우지","ja":"お前が寝てる間に、仕事を済ませてやるよ。","kana":"おまえが ねてる あいだに、しごとを すませて やるよ。","ko":"네가 자는 사이에 일을 끝내 주마."}],"words":[{"w":"間","r":"あいだ","ko":"사이, 동안"},{"w":"裏切り","r":"うらぎり","ko":"배신"},{"w":"謝罪","r":"しゃざい","ko":"사죄"},{"w":"二人きり","r":"ふたりきり","ko":"단둘이"},{"w":"お見舞い","r":"おみまい","ko":"병문안"},{"w":"連れ","r":"つれ","ko":"일행, 동행"},{"w":"家庭","r":"かてい","ko":"가정"},{"w":"留守","r":"るす","ko":"부재중, 집을 비움"}],"grammar":{"point":"〜間 / 〜間に","desc":"〜間(あいだ)는 '~하는 동안 (내내)'로, 그 기간 처음부터 끝까지 같은 상태나 동작이 계속될 때 씁니다(会議の間、ずっと座っていた). 〜間に는 '~하는 동안에, ~하는 사이에'로, 그 기간 중 어느 한 시점에 일이 일어났을 때 씁니다(寝ている間に雨が降った). 즉 뒤 문장이 '계속'이면 間, '한 번 일어난 일'이면 間に입니다. 동사는 〜ている형과 자주 어울리고, 명사는 の를 넣어 夏休みの間・留守の間に처럼 씁니다.","ex":[{"ja":"会議の間、携帯電話の電源を切ってください。","kana":"かいぎの あいだ、けいたい でんわの でんげんを きって ください。","ko":"회의하는 동안 휴대폰 전원을 꺼 주세요."},{"ja":"留守の間に、お客様からお電話がありました。","kana":"るすの あいだに、おきゃくさまから おでんわが ありました。","ko":"자리를 비운 사이에 고객님께 전화가 왔었습니다."}]},"convert":{"anime":"俺がいない間に勝手なことすんなよ。","real":"私が不在の間に何かありましたら、ご連絡ください。","note":"すんな는 するな(하지 마)의 거친 축약이고 명령조라 동료나 고객에게 쓰기 어렵습니다. 업무에서는 不在の間に로 상황을 말하고 ご連絡ください로 정중하게 부탁합니다."},"mission":"출장이나 여행 중에 하고 싶은 일, 또는 자리를 비운 사이에 생긴 일을 〜間 / 〜間に로 말해 보세요.","missionEx":{"ja":"日本にいる間に、温泉に行きたいです。","kana":"にほんに いる あいだに、おんせんに いきたいです。","ko":"일본에 있는 동안에 온천에 가고 싶습니다."},"quiz":[{"q":"「여름방학 동안 내내 일했다」를 일본어로?","choices":["夏休みの間に、ずっと働いた。","夏休みの間、ずっと働いた。","夏休みのうちに、ずっと働いた。"],"a":1,"why":"기간 내내 계속된 동작이므로 に 없이 間을 씁니다."},{"q":"「자는 사이에 비가 왔다」를 일본어로?","choices":["寝ている間、雨が降った。","寝る間で雨が降った。","寝ている間に雨が降った。"],"a":2,"why":"기간 중 한 시점에 일어난 일이므로 間に를 씁니다."},{"q":"「お見舞い」의 뜻은?","choices":["병문안","부재중","배신"],"a":0,"why":"お見舞い(おみまい)는 '병문안'. 부재중은 留守, 배신은 裏切り입니다."}]},"167":{"day":167,"ep":"28","epTitle":"懐玉-肆-","epTitleKo":"회옥 4","title":"있을 리가 없다 — 〜わけがない","watch":"28화(2기 4화) 전반부 · 고전 결계 입구에서 고죠가 기습당하는 장면","scene":"리코를 무사히 고전 결계 안으로 들여보낸 순간, 긴장이 풀린 고죠의 등 뒤로 후시구로 토우지가 나타난다. 주력이 전혀 없는 토우지는 무하한조차 경계하지 못한 틈을 노려 고죠를 쓰러뜨린다. '최강'이 지는 일은 없을 거라 믿었던 장면이 뒤집힌다.","lines":[{"who":"고죠","ja":"術師でもない奴に、この俺が負けるわけがない。","kana":"じゅつし でも ない やつ に、 この おれ が まける わけ が ない。","ko":"술사도 아닌 놈한테 이 내가 질 리가 없어."},{"who":"토우지","ja":"呪力ゼロの俺の気配に、気づけるわけがねぇよ。","kana":"じゅりょく ゼロ の おれ の けはい に、 きづける わけ が ねぇ よ。","ko":"주력 제로인 내 기척을 알아챌 수 있을 리가 없지."},{"who":"게토","ja":"悟がこんな所で簡単にやられるわけがない。","kana":"さとる が こんな ところ で かんたん に やられる わけ が ない。","ko":"사토루가 이런 데서 쉽게 당할 리가 없어."}],"words":[{"w":"正直者","r":"しょうじきもの","ko":"정직한 사람"},{"w":"頑固","r":"がんこ","ko":"고집이 셈"},{"w":"けち","r":"けち","ko":"구두쇠, 인색함"},{"w":"招待","r":"しょうたい","ko":"초대"},{"w":"お人好し","r":"おひとよし","ko":"사람 좋음, 호인"},{"w":"双子","r":"ふたご","ko":"쌍둥이"},{"w":"子供","r":"こども","ko":"아이"},{"w":"世話好き","r":"せわずき","ko":"남 돌보기를 좋아함"}],"grammar":{"point":"〜わけがない","desc":"'~할 리가 없다'라는 강한 부정 추측입니다. 말하는 사람이 근거를 가지고 '절대 그럴 수 없다'고 확신할 때 씁니다.\n접속: 동사·い형용사 보통형 + わけがない / な형용사 な + わけがない / 명사 の(である) + わけがない.\n정중하게는 〜わけがありません, 회화에서는 が를 빼고 〜わけない라고도 합니다.\n한국어 '~할 리가 없다'와 거의 1:1로 대응해서 외우기 쉽습니다.","ex":[{"ja":"こんなに安い保険で、全部保障されるわけがありません。","kana":"こんなに やすい ほけん で、 ぜんぶ ほしょう される わけ が ありません。","ko":"이렇게 싼 보험으로 전부 보장될 리가 없습니다."},{"ja":"真面目な彼が約束を忘れるわけがないです。","kana":"まじめ な かれ が やくそく を わすれる わけ が ない です。","ko":"성실한 그가 약속을 잊을 리가 없어요."}]},"convert":{"anime":"そんなの、できるわけねぇだろ。","real":"申し訳ございませんが、それは難しいかと存じます。","note":"わけねぇだろ는 상대를 몰아붙이는 거친 반말입니다. 고객 앞에서 '불가능하다'고 단정하면 실례가 되니, 難しいかと存じます처럼 부드럽게 돌려 말합니다."},"mission":"일본인 고객이 '원금 손실이 절대 없는 고수익 상품'을 찾습니다. 그런 상품은 있을 리가 없다고 정중하게 설명해 보세요.","missionEx":{"ja":"必ずもうかる商品なんて、あるわけがありません。","kana":"かならず もうかる しょうひん なんて、 ある わけ が ありません。","ko":"반드시 돈 버는 상품 같은 건 있을 리가 없습니다."},"quiz":[{"q":"「그가 약속을 잊을 리가 없어요」를 일본어로?","choices":["彼が約束を忘れるわけではないです。","彼が約束を忘れるわけがないです。","彼が約束を忘れるはずだったです。"],"a":1,"why":"'~할 리가 없다'는 〜わけがない입니다. わけではない는 부분 부정이에요."},{"q":"「頑固」의 뜻은?","choices":["고집이 셈","정직한 사람","쌍둥이"],"a":0,"why":"頑固(がんこ)는 '고집이 세다'. 정직한 사람은 正直者, 쌍둥이는 双子입니다."},{"q":"な형용사 「簡単」에 わけがない를 붙인 바른 형태는?","choices":["簡単わけがない","簡単だわけがない","簡単なわけがない"],"a":2,"why":"な형용사는 な를 붙여 〜なわけがない로 접속합니다."}]},"169":{"day":169,"ep":"28","epTitle":"懐玉-肆-","epTitleKo":"회옥 4","title":"꼭 그런 건 아니다 — 〜わけではない","watch":"28화(2기 4화) 중반 · 고전 지하 텐겐의 거처 앞에서 리코가 속마음을 털어놓는 장면","scene":"게토는 리코와 함께 고전 지하 깊은 곳, 텐겐과의 동화를 위한 장소에 도착한다. 게토는 동화를 거부해도 된다고, 그 경우엔 자신과 사토루가 지켜 주겠다고 말한다. 리코는 눈물을 흘리며 '모두와 더 함께 있고 싶다'는 진심을 털어놓고, 게토는 손을 내밀어 함께 돌아가자고 한다.","lines":[{"who":"게토","ja":"無理に同化しなきゃいけないわけではないんだよ。","kana":"むり に どうか しなきゃ いけない わけ では ない んだ よ。","ko":"억지로 동화해야만 하는 건 아니야."},{"who":"리코","ja":"使命が嫌なわけじゃないの。でも、離れたくない。","kana":"しめい が いや な わけ じゃ ない の。 でも、 はなれたく ない。","ko":"사명이 싫은 건 아니야. 그래도 떨어지기 싫어."},{"who":"리코","ja":"本当は…もっとみんなと一緒にいたいよ。","kana":"ほんとう は… もっと みんな と いっしょ に いたい よ。","ko":"사실은… 더 모두랑 함께 있고 싶어."}],"words":[{"w":"甘えん坊","r":"あまえんぼう","ko":"응석꾸러기"},{"w":"本音","r":"ほんね","ko":"본심, 속마음"},{"w":"強がる","r":"つよがる","ko":"강한 척하다"},{"w":"一緒","r":"いっしょ","ko":"함께, 같이"},{"w":"素直","r":"すなお","ko":"솔직함, 순순함"},{"w":"使命","r":"しめい","ko":"사명"},{"w":"温かい","r":"あたたかい","ko":"따뜻하다"},{"w":"親子","r":"おやこ","ko":"부모와 자식"}],"grammar":{"point":"〜わけではない","desc":"'(꼭) ~인 것은 아니다'라는 부분 부정입니다. 상대가 그렇게 생각할 수 있는 내용을 '전부 그런 건 아니다'라고 살짝 부정할 때 씁니다.\n접속은 わけがない와 같습니다(보통형 / な형용사 な / 명사 の・という + わけではない).\n회화에서는 〜わけじゃない, 정중하게는 〜わけではありません.\n전체 부정인 わけがない(~일 리 없다)와 헷갈리지 않도록 주의하세요.","ex":[{"ja":"保険がどれも同じというわけではありません。","kana":"ほけん が どれ も おなじ という わけ では ありません。","ko":"보험이 다 똑같은 건 아닙니다."},{"ja":"残業が嫌なわけではないですが、今日は早めに帰りたいです。","kana":"ざんぎょう が いや な わけ では ない です が、 きょう は はやめ に かえりたい です。","ko":"야근이 싫은 건 아니지만, 오늘은 일찍 퇴근하고 싶어요."}]},"convert":{"anime":"別に嫌なわけじゃねぇよ。","real":"決して嫌というわけではございません。","note":"じゃねぇよ는 남성적인 거친 반말입니다. 업무에서는 わけではございません으로 바꾸고, 決して(결코)를 붙이면 오해를 푸는 뉘앙스가 더 살아납니다."},"mission":"고객이 '보험을 해지하려는 거죠?'라고 묻습니다. 해지하고 싶은 게 아니라 보장을 점검하고 싶을 뿐이라고 대답해 보세요.","missionEx":{"ja":"解約したいわけではありません。保障を見直したいだけです。","kana":"かいやく したい わけ では ありません。 ほしょう を みなおしたい だけ です。","ko":"해지하고 싶은 건 아닙니다. 보장을 다시 점검하고 싶을 뿐이에요."},"quiz":[{"q":"「보험이 다 똑같은 건 아닙니다」에 맞는 표현은?","choices":["同じというわけではありません","同じなわけがありません","同じに違いありません"],"a":0,"why":"'꼭 ~인 건 아니다'라는 부분 부정은 〜わけではありません입니다."},{"q":"「本音」의 뜻은?","choices":["정하다","고르다","본심, 속마음"],"a":2,"why":"本音(ほんね)는 속마음. 정하다는 決める, 고르다는 選ぶ입니다."},{"q":"〜わけではない의 회화체 형태는?","choices":["〜わけないじゃ","〜わけじゃない","〜わけでない"],"a":1,"why":"では가 회화에서 じゃ로 줄어 〜わけじゃない가 됩니다."}]},"170":{"day":170,"ep":"28","epTitle":"懐玉-肆-","epTitleKo":"회옥 4","title":"틀림없다 — 〜に違いない","watch":"28화(2기 4화) 후반 · 지하에 토우지가 나타나 리코가 쓰러지는 장면","scene":"게토가 리코에게 손을 내민 바로 그때, 총성이 울리고 리코가 쓰러진다. 그 자리에 나타난 사람은 토우지. 그가 여기 왔다는 건 사토루가 당했다는 뜻이라는 걸 깨달은 게토는 분노에 차서 토우지 앞에 선다.","lines":[{"who":"게토","ja":"お前がここにいるなら、悟と戦ったに違いない。","kana":"おまえ が ここ に いる なら、 さとる と たたかった に ちがいない。","ko":"네가 여기 있다면, 사토루와 싸운 게 틀림없어."},{"who":"토우지","ja":"依頼は依頼だ。報酬さえもらえりゃ文句はねぇ。","kana":"いらい は いらい だ。 ほうしゅう さえ もらえりゃ もんく は ねぇ。","ko":"의뢰는 의뢰야. 보수만 받으면 불만은 없어."},{"who":"게토","ja":"理由はどうあれ、お前だけは許さない。","kana":"りゆう は どう あれ、 おまえ だけ は ゆるさない。","ko":"이유가 어떻든, 너만은 용서하지 않아."}],"words":[{"w":"依頼","r":"いらい","ko":"의뢰"},{"w":"借り","r":"かり","ko":"빚, 신세"},{"w":"きっかけ","r":"きっかけ","ko":"계기"},{"w":"訪問","r":"ほうもん","ko":"방문"},{"w":"親戚","r":"しんせき","ko":"친척"},{"w":"従兄弟","r":"いとこ","ko":"사촌"},{"w":"報酬","r":"ほうしゅう","ko":"보수, 대가"},{"w":"叔母","r":"おば","ko":"고모, 이모"}],"grammar":{"point":"〜に違いない","desc":"'~임에 틀림없다'라는 강한 확신의 추측입니다. 눈앞의 근거를 보고 '분명 그렇다'고 판단할 때 씁니다.\n접속: 동사·い형용사 보통형 + に違いない / な형용사·명사는 だ 없이 바로 + に違いない(静かに違いない, 犯人に違いない).\n정중하게는 〜に違いありません. 〜と思います보다 확신이 훨씬 강하고, 글이나 격식 있는 말에서 자주 씁니다.","ex":[{"ja":"電気が消えているから、部長はもう帰ったに違いありません。","kana":"でんき が きえて いる から、 ぶちょう は もう かえった に ちがいありません。","ko":"불이 꺼져 있으니 부장님은 이미 퇴근하신 게 틀림없습니다."},{"ja":"このプランなら、お客様も喜ぶに違いないです。","kana":"この プラン なら、 おきゃくさま も よろこぶ に ちがいない です。","ko":"이 플랜이라면 고객님도 분명 기뻐하실 거예요."}]},"convert":{"anime":"あいつがやったに違いねぇ。","real":"あの方が担当されたに違いないと思います。","note":"違いねぇ는 거친 반말 축약입니다. 회사에서는 あいつ 대신 あの方, 끝은 違いないと思います나 違いありません으로 정중하게 말합니다."},"mission":"동료가 '그 고객, 계약할까요?'라고 묻습니다. 상담 반응이 좋았으니 분명 계약할 거라고 대답해 보세요.","missionEx":{"ja":"反応がよかったので、きっと契約されるに違いありません。","kana":"はんのう が よかった ので、 きっと けいやく される に ちがいありません。","ko":"반응이 좋았으니 분명 계약하실 게 틀림없습니다."},"quiz":[{"q":"명사 「犯人」에 に違いない를 붙인 바른 형태는?","choices":["犯人だに違いない","犯人に違いない","犯人のに違いない"],"a":1,"why":"명사·な형용사는 だ 없이 바로 に違いない를 붙입니다."},{"q":"「従兄弟」의 읽기는?","choices":["いとこ","じゅうけいてい","おじ"],"a":0,"why":"従兄弟는 특별한 읽기로 いとこ(사촌). おじ는 叔父(삼촌)입니다."},{"q":"〜に違いない와 가장 가까운 뜻은?","choices":["~할 리가 없다","~인 건 아니다","~임에 틀림없다"],"a":2,"why":"に違いない는 강한 확신의 추측 '~임에 틀림없다'입니다."}]},"171":{"day":171,"ep":"28","epTitle":"懐玉-肆-","epTitleKo":"회옥 4","title":"~할 예정이었다 — 〜はずだった","watch":"28화(2기 4화) 마지막 · 게토와 토우지의 대결 장면","scene":"게토는 수많은 주령을 불러내 토우지와 맞서지만, 주구를 자유자재로 다루는 토우지에게 밀리고 결국 쓰러진다. 리코는 모두와 함께 돌아갈 예정이었고, 임무는 무사히 끝날 예정이었다. 계획이 모두 무너진 채 화가 끝난다.","lines":[{"who":"게토","ja":"理子ちゃんは、みんなと一緒に帰るはずだった。","kana":"りこ ちゃん は、 みんな と いっしょ に かえる はず だった。","ko":"리코는 모두와 함께 돌아갈 예정이었어."},{"who":"게토","ja":"この呪霊たちなら、勝てるはずだったのに。","kana":"この じゅれい たち なら、 かてる はず だった のに。","ko":"이 주령들이라면 이길 수 있을 터였는데."},{"who":"토우지","ja":"術師ってのは、どいつもこいつも甘ぇな。","kana":"じゅつし って の は、 どいつ も こいつ も あめぇ な。","ko":"술사란 놈들은 하나같이 물러터졌군."}],"words":[{"w":"乗り過ごす","r":"のりすごす","ko":"(내릴 곳을) 지나치다"},{"w":"指定席","r":"していせき","ko":"지정석"},{"w":"結ぶ","r":"むすぶ","ko":"맺다, 묶다"},{"w":"自由席","r":"じゆうせき","ko":"자유석"},{"w":"特急","r":"とっきゅう","ko":"특급(열차)"},{"w":"手続き","r":"てつづき","ko":"절차, 수속"},{"w":"悔しい","r":"くやしい","ko":"분하다"},{"w":"夜行バス","r":"やこうバス","ko":"야간버스"}],"grammar":{"point":"〜はずだった","desc":"'(원래는) ~할 예정이었다 / ~했을 터였다'라는 뜻으로, 당연히 그렇게 될 줄 알았는데 실제로는 그렇게 되지 않았을 때 씁니다.\n접속: 동사·い형용사 보통형 + はずだった / な형용사 な, 명사 の + はずだった.\n뒤에 のに(~인데)를 붙이면 아쉬움·억울함이 강해집니다.\n정중하게는 〜はずでした. 업무에서 일정이 틀어진 상황을 설명할 때 아주 자주 씁니다.","ex":[{"ja":"書類は昨日届くはずだったんですが、まだ来ていません。","kana":"しょるい は きのう とどく はず だった ん です が、 まだ きて いません。","ko":"서류는 어제 도착할 예정이었는데 아직 안 왔습니다."},{"ja":"本当は今日、契約を結ぶはずでした。","kana":"ほんとう は きょう、 けいやく を むすぶ はず でした。","ko":"원래는 오늘 계약을 맺을 예정이었습니다."}]},"convert":{"anime":"今日で終わるはずだったんだけどさ。","real":"本日中に完了する予定でしたが、遅れております。申し訳ございません。","note":"〜んだけどさ는 친구끼리의 반말입니다. 고객에게는 本日中に(오늘 중으로), 遅れております(늦어지고 있습니다)처럼 정중어로 바꾸고 사과를 덧붙입니다."},"mission":"고객에게 전화로 '청약 서류 처리가 지난주에 끝날 예정이었는데 늦어지고 있다'고 사과하며 설명해 보세요.","missionEx":{"ja":"手続きは先週終わるはずでしたが、少し遅れております。","kana":"てつづき は せんしゅう おわる はず でした が、 すこし おくれて おります。","ko":"절차는 지난주에 끝날 예정이었는데 조금 늦어지고 있습니다."},"quiz":[{"q":"「원래 오늘 계약할 예정이었습니다」에 맞는 표현은?","choices":["今日契約するわけがありません。","今日契約するに違いありません。","今日契約するはずでした。"],"a":2,"why":"예정대로 되지 않은 일은 〜はずでした(はずだった)로 말합니다."},{"q":"「悔しい」의 뜻은?","choices":["분하다","계획","실패"],"a":0,"why":"悔しい(くやしい)는 분하다. 계획은 計画, 실패는 失敗입니다."},{"q":"명사 「休み」에 はずだった를 붙인 바른 형태는?","choices":["休みなはずだった","休みのはずだった","休みはずだった"],"a":1,"why":"명사는 の를 넣어 〜のはずだった로 접속합니다."}]},"172":{"day":172,"ep":"29","epTitle":"玉折","epTitleKo":"옥절","title":"~하려고 하다 — 〜ようとする","watch":"29화 전반부 · 무더운 여름, 혼자 임무가 늘어난 게토의 장면","scene":"고죠가 혼자서도 모든 것을 해낼 만큼 강해진 뒤, 게토는 혼자 맡는 임무가 많아집니다. 여름 내내 지친 기색을 숨기려 하지만, 후배 하이바라와 대화할 때도 표정은 어딘가 무겁습니다.","lines":[{"who":"하이바라","ja":"先輩、最近元気がないですね。何かありましたか。","kana":"せんぱい、さいきん げんきが ないですね。なにか ありましたか。","ko":"선배, 요즘 기운이 없으시네요. 무슨 일 있으셨어요?"},{"who":"게토","ja":"いや、疲れを隠そうとしてるだけだよ。","kana":"いや、つかれを かくそうと してる だけだよ。","ko":"아니, 피곤한 걸 숨기려고 하는 것뿐이야."},{"who":"게토","ja":"笑おうとしても、うまく笑えないんだ。","kana":"わらおうと しても、うまく わらえないんだ。","ko":"웃으려고 해도 잘 웃어지지가 않아."}],"words":[{"w":"疲れ果てる","r":"つかれはてる","ko":"녹초가 되다"},{"w":"後輩","r":"こうはい","ko":"후배"},{"w":"笑顔","r":"えがお","ko":"웃는 얼굴"},{"w":"涙もろい","r":"なみだもろい","ko":"눈물이 많다"},{"w":"片思い","r":"かたおもい","ko":"짝사랑"},{"w":"喧嘩","r":"けんか","ko":"싸움, 다툼"},{"w":"寄り道","r":"よりみち","ko":"(가는 길에) 들름"},{"w":"夏","r":"なつ","ko":"여름"}],"grammar":{"point":"〜ようとする","desc":"동사의 의지형(〜よう/〜おう)에 とする를 붙이면 '~하려고 하다'라는 뜻이 됩니다. 1그룹은 끝음을 お단으로 바꾸고 う를 붙이고(隠す→隠そう), 2그룹은 る를 떼고 よう를 붙입니다(止める→止めよう). する→しよう, 来る→こようとする입니다. 막 하려는 순간(出かけようとしたとき)이나, 애써 시도했지만 잘 안 되는 상황(〜ようとしても〜ない)에 자주 씁니다. 한국어 '~하려고 하다/했다'와 거의 같습니다.","ex":[{"ja":"会社を出ようとしたとき、お客様から電話が来ました。","kana":"かいしゃを でようと した とき、おきゃくさまから でんわが きました。","ko":"회사를 나서려고 할 때 고객님께 전화가 왔습니다."},{"ja":"毎日早く寝ようとしていますが、なかなかできません。","kana":"まいにち はやく ねようと して いますが、なかなか できません。","ko":"매일 일찍 자려고 하는데 좀처럼 잘 안 됩니다."}]},"convert":{"anime":"隠そうとしてるだけだよ。","real":"隠そうとしているだけです。","note":"〜てる는 〜ている의 구어 축약이고 だよ는 친구끼리 쓰는 반말입니다. 회사나 고객 앞에서는 い를 살려 〜ている, 끝을 です로 맺습니다."},"mission":"요즘 고치려고 노력 중인 습관이나 하려고 했는데 못 한 일을 〜ようとする로 말해 보세요. 예: 고객 상담 전에 자료를 미리 읽으려고 한다.","missionEx":{"ja":"相談の前に、資料を読んでおこうとしています。","kana":"そうだんの まえに、しりょうを よんで おこうと して います。","ko":"상담 전에 자료를 미리 읽어 두려고 하고 있습니다."},"quiz":[{"q":"「숨기려고 하다」를 일본어로?","choices":["隠そうとする","隠すとする","隠しようとする"],"a":0,"why":"隠す(1그룹)의 의지형은 隠そう이고, 여기에 とする를 붙입니다."},{"q":"「止める」의 〜ようとする 형태는?","choices":["止めろうとする","止めようとする","止まろうとする"],"a":1,"why":"2그룹 동사는 る를 떼고 ようとする를 붙입니다."},{"q":"「笑顔」의 뜻은?","choices":["눈물","화난 얼굴","웃는 얼굴"],"a":2,"why":"笑顔(えがお)는 웃는 얼굴, 미소입니다."}]},"173":{"day":173,"ep":"29","epTitle":"玉折","epTitleKo":"옥절","title":"~하기로 하고 있다(습관) — 〜ことにしている","watch":"29화 전반부 · 게토가 저주를 흡수하는 술식의 고충을 떠올리는 장면","scene":"게토의 술식은 쓰러뜨린 저주를 구슬로 만들어 삼키는 것입니다. 그 맛은 끔찍하지만, 그는 아무 말 없이 매번 참고 삼키기로 정해 두고 있었습니다. 그 습관 뒤에는 '약자를 지킨다'는 신념이 있었습니다.","lines":[{"who":"게토","ja":"どんなに苦くても、黙って飲み込むことにしている。","kana":"どんなに にがくても、だまって のみこむ ことに して いる。","ko":"아무리 써도 말없이 삼키기로 하고 있어."},{"who":"게토","ja":"この味のことは、誰にも話さないことにしてるんだ。","kana":"この あじの ことは、だれにも はなさない ことに してるんだ。","ko":"이 맛에 대해선 아무한테도 말하지 않기로 했어."},{"who":"고죠","ja":"お前、たまには俺に頼ってもいいんだぞ。","kana":"おまえ、たまには おれに たよっても いいんだぞ。","ko":"너, 가끔은 나한테 기대도 된다고."}],"words":[{"w":"お弁当","r":"おべんとう","ko":"도시락"},{"w":"味","r":"あじ","ko":"맛"},{"w":"苦い","r":"にがい","ko":"쓰다(맛)"},{"w":"手料理","r":"てりょうり","ko":"손수 만든 요리"},{"w":"墓参り","r":"はかまいり","ko":"성묘"},{"w":"日記","r":"にっき","ko":"일기"},{"w":"早起き","r":"はやおき","ko":"일찍 일어남"},{"w":"毎週","r":"まいしゅう","ko":"매주"}],"grammar":{"point":"〜ことにしている","desc":"동사 사전형/ない형 + ことにしている는 '(스스로 정해서) ~하기로 하고 있다', 즉 개인적인 규칙·습관을 나타냅니다. 〜ことにする(~하기로 하다)가 한 번의 결정이라면, 〜ことにしている는 그 결정이 계속 지켜지는 상태입니다. 부정은 〜ないことにしている(~하지 않기로 하고 있다)입니다. 회화에서는 〜ことにしてる로 줄여 말합니다. 한국어 '나는 ~하는 걸 원칙으로 하고 있다'에 가깝습니다.","ex":[{"ja":"毎朝、必ず日記を書くことにしています。","kana":"まいあさ、かならず にっきを かく ことに して います。","ko":"매일 아침 반드시 일기를 쓰기로 하고 있습니다."},{"ja":"お客様との約束には、十分前に着くことにしています。","kana":"おきゃくさまとの やくそくには、じっぷん まえに つく ことに して います。","ko":"고객님과의 약속에는 10분 전에 도착하기로 하고 있습니다."}]},"convert":{"anime":"誰にも話さないことにしてるんだ。","real":"誰にも話さないことにしているんです。","note":"〜してるんだ는 친구끼리의 반말 축약입니다. 업무 자리에서는 〜しているんです로 풀어서 말하면 개인 원칙을 정중하게 설명할 수 있습니다."},"mission":"일이나 생활에서 스스로 지키고 있는 규칙을 〜ことにしている로 소개해 보세요. 예: 매주 금요일에는 고객 연락을 정리한다.","missionEx":{"ja":"毎週金曜日は、お客様への連絡をまとめることにしています。","kana":"まいしゅう きんようびは、おきゃくさまへの れんらくを まとめる ことに して います。","ko":"매주 금요일에는 고객 연락을 정리하기로 하고 있습니다."},"quiz":[{"q":"「(습관으로) 술을 마시지 않기로 하고 있습니다」는?","choices":["お酒を飲まないことになっています。","お酒を飲むことにしません。","お酒を飲まないことにしています。"],"a":2,"why":"스스로 정한 습관은 〜ないことにしている입니다. 〜ことになっている는 남이 정한 규칙입니다."},{"q":"「苦い」의 뜻은?","choices":["쓰다","달다","맵다"],"a":0,"why":"苦い(にがい)는 쓴맛입니다. 단맛은 甘い입니다."},{"q":"「일찍 일어남」을 뜻하는 단어는?","choices":["早速","早起き","朝寝坊"],"a":1,"why":"早起き(はやおき)는 일찍 일어나는 것, 朝寝坊는 늦잠입니다."}]},"174":{"day":174,"ep":"29","epTitle":"玉折","epTitleKo":"옥절","title":"~해야 한다(당위) — 〜べきだ","watch":"29화 후반부 · 게토가 외딴 마을에 임무를 나가는 장면","scene":"게토는 임무로 외딴 마을을 찾아갑니다. 그곳에서 마을 사람들이 주력을 가진 어린 두 소녀를 가두고 함부로 대하는 모습을 보게 되고, 그동안 지켜야 한다고 믿었던 것이 크게 흔들립니다. 그 선택은 결국 돌이킬 수 없는 비극으로 이어집니다.","lines":[{"who":"게토","ja":"この子たちを、すぐにここから出すべきだ。","kana":"この こたちを、すぐに ここから だす べきだ。","ko":"이 아이들을 당장 여기서 꺼내야 해."},{"who":"게토","ja":"私が守るべきものは、本当にこの村なのか。","kana":"わたしが まもる べき ものは、ほんとうに この むら なのか。","ko":"내가 지켜야 할 것은 정말 이 마을인가."},{"who":"게토","ja":"正しい答えが、もう分からなくなった。","kana":"ただしい こたえが、もう わからなく なった。","ko":"옳은 답이 이제 모르겠어."}],"words":[{"w":"村","r":"むら","ko":"마을"},{"w":"長女","r":"ちょうじょ","ko":"장녀"},{"w":"答え","r":"こたえ","ko":"답, 대답"},{"w":"共通","r":"きょうつう","ko":"공통"},{"w":"分ける","r":"わける","ko":"나누다"},{"w":"実家","r":"じっか","ko":"본가, 친정"},{"w":"お袋","r":"おふくろ","ko":"어머니(허물없는 말)"},{"w":"会話","r":"かいわ","ko":"대화, 회화"}],"grammar":{"point":"〜べきだ","desc":"동사 사전형 + べきだ는 '(당연히) ~해야 한다, ~하는 게 맞다'라는 당위·의견을 나타냅니다. する는 するべき 또는 すべき 둘 다 씁니다. 부정은 〜べきではない(~해서는 안 된다)입니다. 〜なければならない가 규칙·사정상 어쩔 수 없는 의무라면, べきだ는 말하는 사람의 가치 판단이 강해서 윗사람에게 직접 쓰면 강하게 들립니다. 명사 수식은 '守るべきもの(지켜야 할 것)'처럼 씁니다.","ex":[{"ja":"保険は、若いうちに準備するべきです。","kana":"ほけんは、わかい うちに じゅんび する べきです。","ko":"보험은 젊을 때 준비하는 것이 좋습니다."},{"ja":"大事な契約は、一人で決めるべきではありません。","kana":"だいじな けいやくは、ひとりで きめる べきでは ありません。","ko":"중요한 계약은 혼자서 결정해서는 안 됩니다."}]},"convert":{"anime":"すぐに出すべきだ。","real":"すぐに出したほうがいいと思います。","note":"べきだ는 단정적이라 고객이나 상사에게 쓰면 훈계처럼 들립니다. 실무에서는 〜たほうがいいと思います로 부드럽게 권하는 것이 자연스럽습니다."},"mission":"고객에게 꼭 필요하다고 생각하는 재무 습관을 〜べきだ와 부드러운 표현 둘 다로 말해 보세요. 예: 비상금은 미리 준비해야 한다.","missionEx":{"ja":"急な出費のために、貯金はしておくべきです。","kana":"きゅうな しゅっぴの ために、ちょきんは して おく べきです。","ko":"갑작스러운 지출을 위해 저축은 해 둬야 합니다."},"quiz":[{"q":"「지켜야 할 것」을 일본어로?","choices":["守るべきもの","守りべきもの","守ったべきもの"],"a":0,"why":"べき 앞에는 동사 사전형이 옵니다."},{"q":"「〜べきではない」의 뜻은?","choices":["~할 수 없다","~해서는 안 된다","~할 필요가 없다"],"a":1,"why":"べきではない는 '그렇게 하는 것은 옳지 않다'는 당위의 부정입니다."},{"q":"「会話」의 읽기는?","choices":["かいは","がいわ","かいわ"],"a":2,"why":"会話는 かいわ, '대화, 회화'입니다."}]},"176":{"day":176,"ep":"29","epTitle":"玉折","epTitleKo":"옥절","title":"구어 의무 — 〜ないと","watch":"29화 후반부 · 신주쿠 번화가에서 고죠와 게토가 마주하는 장면","scene":"마을 사건 뒤 사라진 게토를, 고죠는 신주쿠 인파 한가운데에서 다시 만납니다. 게토는 자신이 가기로 한 길을 담담히 말하고 등을 돌립니다. 고죠는 그를 붙잡을 수 있었지만 끝내 손을 쓰지 못하고, 둘은 그렇게 갈라섭니다.","lines":[{"who":"고죠","ja":"説明してもらわないと、俺は納得できねえよ。","kana":"せつめい して もらわないと、おれは なっとく できねえよ。","ko":"설명을 들어야겠어. 안 그럼 난 납득 못 해."},{"who":"게토","ja":"悪いね、悟。私はもうあっちへ行かないと。","kana":"わるいね、さとる。わたしは もう あっちへ いかないと。","ko":"미안해, 사토루. 난 이제 저쪽으로 가야 해."},{"who":"게토","ja":"親友でも、ここで別れないといけない。","kana":"しんゆう でも、ここで わかれないと いけない。","ko":"친구라도 여기서 헤어져야 해."}],"words":[{"w":"遠距離","r":"えんきょり","ko":"먼 거리, 장거리"},{"w":"街","r":"まち","ko":"거리, 번화가"},{"w":"人混み","r":"ひとごみ","ko":"인파, 붐빔"},{"w":"帰省","r":"きせい","ko":"귀성, 고향에 내려감"},{"w":"新幹線","r":"しんかんせん","ko":"신칸센"},{"w":"観光地","r":"かんこうち","ko":"관광지"},{"w":"各駅","r":"かくえき","ko":"각 역 정차(완행)"},{"w":"納得","r":"なっとく","ko":"납득"}],"grammar":{"point":"〜ないと (구어 의무)","desc":"〜ないといけない/〜ないとだめ는 '~하지 않으면 안 된다 = ~해야 한다'의 회화체입니다. 친한 사이에서는 뒷부분을 생략하고 〜ないと만으로 '~해야지, ~해야 해'라고 말합니다(もう行かないと). 〜なければなりません보다 훨씬 가볍고 일상적입니다. 정중하게 말할 때는 〜ないといけません을 씁니다. 한국어 '이제 가야지', '빨리 해야 돼'와 같은 느낌입니다.","ex":[{"ja":"あ、もうこんな時間。急がないと。","kana":"あ、もう こんな じかん。いそがないと。","ko":"아, 벌써 시간이 이렇게 됐네. 서둘러야지."},{"ja":"明日までに書類を出さないといけません。","kana":"あしたまでに しょるいを ださないと いけません。","ko":"내일까지 서류를 내야 합니다."}]},"convert":{"anime":"もう行かないと。","real":"そろそろ失礼しないといけませんので。","note":"〜ないと로 끝내는 말은 친구끼리 쓰는 혼잣말 같은 표현입니다. 고객 미팅을 마치고 일어날 때는 失礼する와 〜ないといけませんので를 써서 정중하게 자리를 뜹니다."},"mission":"오늘 꼭 해야 하는 일 2가지를 〜ないと(반말)와 〜ないといけません(정중) 두 가지로 말해 보세요. 예: 고객에게 답장해야 한다.","missionEx":{"ja":"今日中に、お客様にメールを返さないといけません。","kana":"きょうじゅうに、おきゃくさまに めーるを かえさないと いけません。","ko":"오늘 중으로 고객님께 메일 답장을 해야 합니다."},"quiz":[{"q":"「이제 가야 해」를 구어로 자연스럽게?","choices":["もう行かないと。","もう行くないと。","もう行けないと。"],"a":0,"why":"行く의 ない형은 行かない이고, 여기에 と를 붙여 구어 의무를 만듭니다."},{"q":"「〜ないと」를 정중하게 말하면?","choices":["〜ないとです","〜ないといけません","〜ないでください"],"a":1,"why":"정중체는 〜ないといけません입니다. 〜ないでください는 '~하지 마세요'입니다."},{"q":"「人混み」의 뜻은?","choices":["사람 이름","혼자 있음","인파, 붐빔"],"a":2,"why":"人混み(ひとごみ)는 사람이 많이 붐비는 곳입니다."}]},"177":{"day":177,"ep":"30","epTitle":"そういうこと","epTitleKo":"그런 거야","title":"~에 대해서 — 〜について","watch":"30화 전반부 · 메카마루(무타 코키치)가 마히토와의 거래를 정리하는 장면","scene":"교토교 2학년 메카마루의 본체 무타 코키치는 태어날 때부터 몸이 자유롭지 않았습니다. 그는 몸을 고쳐 주겠다는 조건으로 저주 측과 거래를 했고, 그 약속이 지켜진 뒤 이제 거래를 끝내려 합니다. 하지만 마히토는 순순히 보내 줄 생각이 없습니다.","lines":[{"who":"메카마루","ja":"取引の条件について、もう一度確認したい。","kana":"とりひきの じょうけんに ついて、もう いちど かくにん したい。","ko":"거래 조건에 대해서 한 번 더 확인하고 싶다."},{"who":"마히토","ja":"君の体については、ちゃんと約束を守ったよ。","kana":"きみの からだに ついては、ちゃんと やくそくを まもったよ。","ko":"네 몸에 대해서는 제대로 약속 지켰잖아."},{"who":"메카마루","ja":"お前たちの計画について、全部話してもらう。","kana":"おまえたちの けいかくに ついて、ぜんぶ はなして もらう。","ko":"너희 계획에 대해 전부 말하게 해 주지."}],"words":[{"w":"取引","r":"とりひき","ko":"거래"},{"w":"方言","r":"ほうげん","ko":"사투리"},{"w":"旅行者","r":"りょこうしゃ","ko":"여행자"},{"w":"情報","r":"じょうほう","ko":"정보"},{"w":"両替","r":"りょうがえ","ko":"환전"},{"w":"時差","r":"じさ","ko":"시차"},{"w":"文通","r":"ぶんつう","ko":"편지 주고받기"},{"w":"出国","r":"しゅっこく","ko":"출국"}],"grammar":{"point":"〜について","desc":"명사 + について는 '~에 대해서, ~에 관해서'라는 뜻으로 이야기·생각·조사의 주제를 나타냅니다. 뒤에 話す・聞く・考える・調べる・説明する 같은 동사가 잘 옵니다. 명사를 꾸밀 때는 〜についての(~에 대한)를 씁니다(保険についての質問). 주제를 강조하거나 대비할 때는 〜については를 씁니다. 격식 있는 문서에서는 〜に関して도 비슷하게 씁니다.","ex":[{"ja":"新しい保険について、詳しく説明させていただきます。","kana":"あたらしい ほけんに ついて、くわしく せつめい させて いただきます。","ko":"새 보험에 대해 자세히 설명드리겠습니다."},{"ja":"老後の資金についての相談が増えています。","kana":"ろうごの しきんに ついての そうだんが ふえて います。","ko":"노후 자금에 대한 상담이 늘고 있습니다."}]},"convert":{"anime":"計画について全部話してもらう。","real":"計画について、詳しく教えていただけますか。","note":"〜てもらう로 단정하면 명령처럼 들립니다. 상대에게 정보를 요청할 때는 〜ていただけますか로 물어야 정중합니다."},"mission":"일본인 고객이 상담 예약을 하려 합니다. 〜について를 써서 어떤 주제로 상담하고 싶은지 묻고, 예시 답을 말해 보세요.","missionEx":{"ja":"どの保険について、ご相談されたいですか。","kana":"どの ほけんに ついて、ごそうだん されたい ですか。","ko":"어떤 보험에 대해 상담을 원하십니까?"},"quiz":[{"q":"「보험에 대한 질문」을 일본어로?","choices":["保険についての質問","保険についての質問です","保険について質問の"],"a":0,"why":"명사를 꾸밀 때는 〜についての + 명사 형태를 씁니다."},{"q":"「取引」의 뜻은?","choices":["약속","계획","거래"],"a":2,"why":"取引(とりひき)는 거래입니다. 계획은 計画입니다."},{"q":"빈칸에 맞는 것은? 「将来の計画（　）話しましょう。」","choices":["にとって","について","によって"],"a":1,"why":"이야기의 주제를 나타낼 때는 について입니다."}]},"178":{"day":178,"ep":"30","epTitle":"そういうこと","epTitleKo":"그런 거야","title":"~에 의해/~에 따라 — 〜によって","watch":"30화 중반부 · '궁극 메카마루'가 출격하는 장면","scene":"메카마루는 오랫동안 몸을 쓰지 못한 대신 쌓아 온 막대한 주력을 거대한 기체 '궁극 메카마루'에 담아 두었습니다. 그는 오랜 세월의 준비로 만든 이 비장의 수로 마히토와 정면으로 맞섭니다.","lines":[{"who":"메카마루","ja":"長年ためた力によって、この機械は動いている。","kana":"ながねん ためた ちからに よって、この きかいは うごいて いる。","ko":"오랜 세월 모은 힘으로 이 기계는 움직이고 있다."},{"who":"마히토","ja":"へえ、相手によって準備を変えたんだね。","kana":"へえ、あいてに よって じゅんびを かえたんだね。","ko":"헤에, 상대에 따라 준비를 바꿨구나."},{"who":"메카마루","ja":"この戦いの結果は、次の一撃によって決まる。","kana":"この たたかいの けっかは、つぎの いちげきに よって きまる。","ko":"이 싸움의 결과는 다음 일격으로 정해진다."}],"words":[{"w":"運賃","r":"うんちん","ko":"운임, 요금"},{"w":"長年","r":"ながねん","ko":"오랜 세월"},{"w":"泊まる","r":"とまる","ko":"묵다, 숙박하다"},{"w":"日帰り","r":"ひがえり","ko":"당일치기"},{"w":"見物","r":"けんぶつ","ko":"구경"},{"w":"名所","r":"めいしょ","ko":"명소"},{"w":"年齢","r":"ねんれい","ko":"나이, 연령"},{"w":"乗車","r":"じょうしゃ","ko":"승차"}],"grammar":{"point":"〜によって","desc":"명사 + によって는 크게 세 가지로 씁니다. ① 수단·원인: '~에 의해, ~로'(努力によって成功した). ② 차이: '~에 따라 (다르다)'(人によって違う). ③ 수동문의 행위자: '~에 의해'(この絵はピカソによって描かれた). 특히 '~에 따라 다르다'는 상담·설명에서 매우 자주 씁니다. 명사를 꾸밀 때는 〜による(年齢による違い)를 씁니다.","ex":[{"ja":"保険料は、年齢によって違います。","kana":"ほけんりょうは、ねんれいに よって ちがいます。","ko":"보험료는 나이에 따라 다릅니다."},{"ja":"お客様によって、合う方法が変わります。","kana":"おきゃくさまに よって、あう ほうほうが かわります。","ko":"고객님에 따라 맞는 방법이 달라집니다."}]},"convert":{"anime":"相手によって準備を変えたんだね。","real":"お客様によって、ご提案を変えております。","note":"〜たんだね는 친구끼리의 반말입니다. 업무에서는 お客様・ご提案처럼 높임말을 쓰고 〜ております로 겸손하게 말합니다."},"mission":"고객이 '보험료는 다 똑같나요?'라고 묻습니다. 〜によって違います를 써서 무엇에 따라 달라지는지 설명해 보세요.","missionEx":{"ja":"いいえ、年齢や健康状態によって違います。","kana":"いいえ、ねんれいや けんこう じょうたいに よって ちがいます。","ko":"아니요, 나이나 건강 상태에 따라 다릅니다."},"quiz":[{"q":"「사람에 따라 다릅니다」를 일본어로?","choices":["人について違います。","人にとって違います。","人によって違います。"],"a":2,"why":"'~에 따라 다르다'는 〜によって違う입니다."},{"q":"「나이에 따른 차이」에서 명사를 꾸미는 형태는?","choices":["年齢による違い","年齢によって違い","年齢にの違い"],"a":0,"why":"명사 수식은 〜による + 명사입니다."},{"q":"「長年」의 뜻은?","choices":["내년","오랜 세월","작년"],"a":1,"why":"長年(ながねん)는 '오랜 세월, 여러 해'입니다."}]},"179":{"day":179,"ep":"30","epTitle":"そういうこと","epTitleKo":"그런 거야","title":"~에 대해(대상·태도) — 〜に対して","watch":"30화 중반부 · 궁극 메카마루와 마히토의 격전 장면","scene":"메카마루는 마히토를 향해 쌓아 둔 주력을 아낌없이 쏟아붓고, 마히토는 장난치듯 상대의 공격을 받아넘깁니다. 진지한 메카마루와 끝까지 사람을 깔보는 마히토의 태도가 강하게 대비되는 싸움입니다.","lines":[{"who":"메카마루","ja":"お前に対して、手加減するつもりはない。","kana":"おまえに たいして、てかげん する つもりは ない。","ko":"너에게 봐줄 생각은 없다."},{"who":"마히토","ja":"必死な人に対しては、つい遊びたくなるんだよ。","kana":"ひっしな ひとに たいしては、つい あそびたく なるんだよ。","ko":"필사적인 사람한테는 그만 장난치고 싶어지거든."},{"who":"메카마루","ja":"その態度に対して、怒る気にもならない。","kana":"その たいどに たいして、おこる きにも ならない。","ko":"그 태도에는 화낼 마음도 안 든다."}],"words":[{"w":"態度","r":"たいど","ko":"태도"},{"w":"握手","r":"あくしゅ","ko":"악수"},{"w":"礼儀","r":"れいぎ","ko":"예의"},{"w":"からかう","r":"からかう","ko":"놀리다"},{"w":"反対","r":"はんたい","ko":"반대"},{"w":"見下す","r":"みくだす","ko":"깔보다, 얕보다"},{"w":"敬語","r":"けいご","ko":"경어, 존댓말"},{"w":"丁寧","r":"ていねい","ko":"정중함, 공손함"}],"grammar":{"point":"〜に対して","desc":"명사 + に対して는 '~에 대해서, ~에게(향해서)'라는 뜻으로 행동·감정·태도가 향하는 대상을 나타냅니다(お客様に対して丁寧に話す). について가 '주제'라면 に対して는 '상대·대상'에 초점이 있습니다. 명사를 꾸밀 때는 〜に対する(意見に対する反論)를 씁니다. 또 'A인 것에 비해 B는'처럼 대비를 나타낼 때도 씁니다(兄が静かなのに対して、弟は元気だ).","ex":[{"ja":"お客様に対しては、いつも丁寧に話します。","kana":"おきゃくさまに たいしては、いつも ていねいに はなします。","ko":"고객님께는 항상 정중하게 말합니다."},{"ja":"部長の意見に対して、反対する人はいませんでした。","kana":"ぶちょうの いけんに たいして、はんたい する ひとは いませんでした。","ko":"부장님 의견에 반대하는 사람은 없었습니다."}]},"convert":{"anime":"その態度に対して、怒る気にもならない。","real":"そのご対応に対して、少し残念に思いました。","note":"직장이나 거래처에 불만을 전할 때 '화도 안 난다'처럼 직설적으로 말하면 관계가 틀어집니다. ご対応・残念に思う처럼 완곡하게 표현합니다."},"mission":"고객의 불만에 대해 어떻게 대응하는지 〜に対して를 써서 말해 보세요. 예: 고객 질문에는 바로 답한다.","missionEx":{"ja":"お客様の質問に対しては、その日のうちにお答えしています。","kana":"おきゃくさまの しつもんに たいしては、その ひの うちに おこたえ して います。","ko":"고객님 질문에는 그날 안에 답변드리고 있습니다."},"quiz":[{"q":"「고객에게 정중하게 말한다」에 맞는 조사 표현은? 「お客様（　）丁寧に話す。」","choices":["に対して","によって","について"],"a":0,"why":"태도가 향하는 상대에는 に対して를 씁니다."},{"q":"「의견에 대한 반대」에서 명사를 꾸미는 형태는?","choices":["意見に対して反対","意見に対する反対","意見に対しの反対"],"a":1,"why":"명사 수식은 〜に対する + 명사입니다."},{"q":"「見下す」의 뜻은?","choices":["감사하다","정중하다","깔보다, 얕보다"],"a":2,"why":"見下す(みくだす)는 '깔보다, 얕보다'. 상대를 낮춰 보는 태도입니다."}]}});
